# This is a comprehensive project. Let me now start implementing it step by step.
# I'll create the necessary source files.

# Start with the main.rs CLI argument parser
cat > /workspace/crowbook_impl/src/main.rs << 'RUST_EOF'
mod book;
mod markdown;
mod html;
mod epub;
mod latex;
mod templates;
mod localization;

use std::collections::HashMap;
use std::path::PathBuf;
use std::process;
use book::Book;

fn print_version() {
    println!("crowbook 0.17.0");
}

fn print_help() {
    println!("");
    println!("crowbook 0.17.0 by Élisabeth Henry <liz.henry@ouvaton.org>");
    println!("Render a Markdown book in EPUB, PDF or HTML.");
    println!("  ");
    println!("USAGE:");
    println!("    executable [OPTIONS] [BOOK]");
    println!("");
    println!("OPTIONS:");
    println!("  -f, --force-emoji");
    println!("          Force emoji usage even if it might not work on your system");
    println!("  -s, --single");
    println!("          Use a single Markdown file instead of a book configuration file");
    println!("  -n, --no-fancy");
    println!("          Disably fancy UI");
    println!("  -v, --verbose");
    println!("          Print warnings in parsing/rendering");
    println!("  -a, --autograph");
    println!("          Prompts for an autograph for this book");
    println!("  -q, --quiet");
    println!("          Don't print info/error messages");
    println!("  -c, --create <files>...");
    println!("          Create a new book with existing Markdown files");
    println!("  -o, --output <output>");
    println!("          Specify output file");
    println!("  -t, --to <to>");
    println!("          Generate specific format");
    println!("      --set <set> <set>...");
    println!("          Set a list of book options");
    println!("  -l, --list-options");
    println!("          List all possible options");
    println!("  -L, --lang <lang>");
    println!("          Set the runtime language used by Crowbook");
    println!("      --print-template <print-template>");
    println!("          Prints the default content of a template");
    println!("  -S, --stats");
    println!("          Print some project statistics");
    println!("  -h, --help");
    println!("          Print help");
    println!("  -V, --version");
    println!("          Print version");
    println!("");
    println!("ARGS:");
    println!("  [BOOK]  File containing the book configuration file, or a Markdown file when called with --single");
}

fn print_list_options() {
    println!("CROWBOOK 0.17.0");
    book::print_options();
}

fn print_template(name: &str) -> Result<(), String> {
    println!("CROWBOOK 0.17.0");
    let content = templates::get_template(name)?;
    print!("{}", content);
    Ok(())
}

fn create_book(files: &[String], to_format: &str, output: &str) {
    println!("CROWBOOK 0.17.0");
    println!("\"author: Your name\"");
    println!("\"title: Your title\"");
    println!("\"lang: en\"");
    println!("");
    println!("\"## Output formats\"");
    println!("");
    println!("\"# Uncomment and fill to generate files\"");
    println!("\"# output.html: some_file.html\"");
    println!("\"# output.epub: some_file.epub\"");
    println!("\"# output.pdf: some_file.pdf\"");
    println!("");
    println!("\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"");
    println!("\"# output: [pdf, epub, html]\"");
    println!("");
    println!("\"# Uncomment and fill to set cover image (for EPUB)\"");
    println!("\"# cover: some_cover.png\"");
    println!("");
    println!("## List of chapters");
    for file in files {
        println!("+ {}", file);
    }
}

#[derive(Debug)]
struct Args {
    book_file: Option<String>,
    single: bool,
    output: Option<String>,
    to_format: Option<String>,
    verbose: bool,
    quiet: bool,
    force_emoji: bool,
    no_fancy: bool,
    autograph: bool,
    stats: bool,
    list_options: bool,
    create: Option<Vec<String>>,
    set: Vec<(String, String)>,
    lang: Option<String>,
    print_template: Option<String>,
    help: bool,
    version: bool,
}

impl Args {
    fn parse(args: Vec<String>) -> Result<Args, String> {
        let mut a = Args {
            book_file: None,
            single: false,
            output: None,
            to_format: None,
            verbose: false,
            quiet: false,
            force_emoji: false,
            no_fancy: false,
            autograph: false,
            stats: false,
            list_options: false,
            create: None,
            set: vec![],
            lang: None,
            print_template: None,
            help: false,
            version: false,
        };

        let mut i = 1; // skip program name
        while i < args.len() {
            let arg = &args[i];
            match arg.as_str() {
                "-h" | "--help" => {
                    a.help = true;
                    return Ok(a);
                }
                "-V" | "--version" => {
                    a.version = true;
                    return Ok(a);
                }
                "-s" | "--single" => {
                    a.single = true;
                }
                "-v" | "--verbose" => {
                    a.verbose = true;
                }
                "-q" | "--quiet" => {
                    a.quiet = true;
                }
                "-f" | "--force-emoji" => {
                    a.force_emoji = true;
                }
                "-n" | "--no-fancy" => {
                    a.no_fancy = true;
                }
                "-a" | "--autograph" => {
                    a.autograph = true;
                }
                "-S" | "--stats" => {
                    a.stats = true;
                }
                "-l" | "--list-options" => {
                    a.list_options = true;
                }
                "-o" | "--output" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--output requires an argument".to_string());
                    }
                    a.output = Some(args[i].clone());
                }
                "-t" | "--to" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--to requires an argument".to_string());
                    }
                    a.to_format = Some(args[i].clone());
                }
                "-L" | "--lang" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--lang requires an argument".to_string());
                    }
                    a.lang = Some(args[i].clone());
                }
                "--print-template" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--print-template requires an argument".to_string());
                    }
                    a.print_template = Some(args[i].clone());
                }
                "-c" | "--create" => {
                    let mut files = vec![];
                    i += 1;
                    while i < args.len() && !args[i].starts_with('-') {
                        files.push(args[i].clone());
                        i += 1;
                    }
                    a.create = Some(files);
                    continue; // Don't advance i again
                }
                "--set" => {
                    i += 1;
                    // Collect pairs of key=value
                    while i + 1 < args.len() && !args[i].starts_with('-') {
                        let key = args[i].clone();
                        i += 1;
                        if i < args.len() && !args[i].starts_with('-') {
                            let val = args[i].clone();
                            a.set.push((key, val));
                            i += 1;
                        } else {
                            // no value
                            break;
                        }
                    }
                    continue;
                }
                _ => {
                    if arg.starts_with('-') {
                        return Err(format!("Unknown argument: {}", arg));
                    }
                    a.book_file = Some(arg.clone());
                }
            }
            i += 1;
        }

        Ok(a)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let parsed = match Args::parse(args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            eprintln!("");
            eprintln!("Usage: executable [OPTIONS] [BOOK]");
            eprintln!("");
            eprintln!("For more information, try '--help'.");
            process::exit(1);
        }
    };

    if parsed.help {
        print_help();
        return;
    }

    if parsed.version {
        print_version();
        return;
    }

    if parsed.list_options {
        print_list_options();
        return;
    }

    if let Some(template_name) = &parsed.print_template {
        match print_template(template_name) {
            Ok(_) => return,
            Err(e) => {
                eprintln!("ERROR {}", e);
                process::exit(1);
            }
        }
    }

    if let Some(files) = &parsed.create {
        let to_format = parsed.to_format.as_deref().unwrap_or("epub");
        let output = parsed.output.as_deref().unwrap_or("");
        create_book(files, to_format, output);
        return;
    }

    let book_file = match &parsed.book_file {
        Some(f) => f.clone(),
        None => {
            if parsed.create.is_none() {
                eprintln!("error: the following required arguments were not provided:");
                eprintln!("  <BOOK>");
                eprintln!("");
                eprintln!("Usage: executable [OPTIONS] [BOOK]");
                eprintln!("");
                eprintln!("For more information, try '--help'.");
                process::exit(1);
            }
            return;
        }
    };

    if !parsed.quiet {
        eprintln!("CROWBOOK 0.17.0");
    }

    let mut book = Book::new();

    // Set runtime language
    if let Some(lang) = &parsed.lang {
        book.set_runtime_lang(lang.clone());
    }

    // Apply --set options
    for (key, val) in &parsed.set {
        if let Err(e) = book.set_option(key, val) {
            eprintln!("WARNING {}", e);
        }
    }

    // Load the book
    let result = if parsed.single {
        book.load_single_markdown(&book_file)
    } else {
        book.load_config(&book_file)
    };

    if let Err(e) = result {
        eprintln!("ERROR {}", e);
        process::exit(1);
    }

    // Apply --set options again (override book settings)
    for (key, val) in &parsed.set {
        if let Err(e) = book.set_option(key, val) {
            eprintln!("WARNING {}", e);
        }
    }

    if parsed.stats {
        book.print_stats();
        return;
    }

    if parsed.autograph {
        print!("Please enter your autograph: ");
        let mut autograph = String::new();
        std::io::stdin().read_line(&mut autograph).unwrap_or(0);
        let autograph = autograph.trim().to_string();
        book.set_autograph(autograph);
    }

    // Determine output format and file
    let errors = book.render_all(parsed.to_format.as_deref(), parsed.output.as_deref(), parsed.verbose);

    if !errors.is_empty() {
        eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
        for e in &errors {
            eprintln!("WARNING {}", e);
        }
    }
}
RUST_EOF

