/// Represents a single markdown element/token
#[derive(Debug, Clone)]
pub enum Token {
    Str(String),
    Paragraph(Vec<Token>),
    Header(u32, Vec<Token>),  // (level, content)
    Em(Vec<Token>),
    Strong(Vec<Token>),
    Code(String),  // inline code
    CodeBlock(Option<String>, String),  // (language, content)
    BlockQuote(Vec<Token>),
    List(bool, Vec<ListItem>),  // (ordered, items)
    Rule,
    HardBreak,
    SoftBreak,
    Link(String, String, Vec<Token>),  // (href, title, content)
    Image(String, String, String),  // (href, title, alt)
    Table(Vec<Vec<Vec<Token>>>, Vec<Alignment>),  // (rows, alignments)
    Footnote(u32),  // reference number
    FootnoteDefinition(u32, Vec<Token>),  // (number, content)
    Strikethrough(Vec<Token>),
    Superscript(Vec<Token>),
    Subscript(Vec<Token>),
    TaskItem(bool, Vec<Token>),  // (checked, content)
    Html(String),
    // Document-level
    Chapter(Vec<Token>),  // A top-level section  
}

#[derive(Debug, Clone)]
pub struct ListItem {
    pub is_task: Option<bool>,  // None = not a task item, Some(checked) = task item
    pub content: Vec<Token>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Alignment {
    Left,
    Center,
    Right,
    None,
}

/// Parse a markdown string into a list of tokens
pub fn parse(input: &str, superscript: bool) -> Vec<Token> {
    let mut parser = MarkdownParser::new(input, superscript);
    parser.parse()
}

struct MarkdownParser {
    chars: Vec<char>,
    pos: usize,
    superscript_enabled: bool,
    footnote_defs: Vec<(String, Vec<Token>)>,
    footnote_counter: u32,
}

impl MarkdownParser {
    fn new(input: &str, superscript: bool) -> Self {
        MarkdownParser {
            chars: input.chars().collect(),
            pos: 0,
            superscript_enabled: superscript,
            footnote_defs: vec![],
            footnote_counter: 0,
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn remaining(&self) -> &[char] {
        &self.chars[self.pos..]
    }

    fn at_line_start(&self) -> bool {
        self.pos == 0 || self.chars.get(self.pos.saturating_sub(1)) == Some(&'\n')
    }

    // Get current line
    fn current_line(&self) -> String {
        let start = self.pos;
        let mut end = start;
        while end < self.chars.len() && self.chars[end] != '\n' {
            end += 1;
        }
        self.chars[start..end].iter().collect()
    }

    // Advance until end of line
    fn advance_line(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos] != '\n' {
            self.pos += 1;
        }
        if self.pos < self.chars.len() {
            self.pos += 1; // consume newline
        }
    }

    // Skip whitespace on current line
    fn skip_spaces(&mut self) {
        while self.peek() == Some(' ') || self.peek() == Some('\t') {
            self.advance();
        }
    }

    // Count and skip leading spaces
    fn count_leading_spaces(&self) -> usize {
        let mut count = 0;
        let mut pos = self.pos;
        while pos < self.chars.len() && (self.chars[pos] == ' ' || self.chars[pos] == '\t') {
            if self.chars[pos] == '\t' {
                count += 4;
            } else {
                count += 1;
            }
            pos += 1;
        }
        count
    }

    fn parse(&mut self) -> Vec<Token> {
        let mut blocks = vec![];

        // First pass: extract footnote definitions
        let text = self.chars.iter().collect::<String>();
        let mut remaining_text = String::new();
        let mut footnote_map: std::collections::HashMap<String, Vec<Token>> = std::collections::HashMap::new();

        // Parse the document
        self.parse_blocks(&text)
    }

    fn parse_blocks(&mut self, text: &str) -> Vec<Token> {
        // Split into lines and process
        let lines: Vec<&str> = text.lines().collect();
        let mut blocks: Vec<Token> = vec![];
        let mut i = 0;
        let total = lines.len();
        let mut footnote_defs: Vec<(String, String)> = vec![];

        while i < total {
            let line = lines[i];
            let trimmed = line.trim();

            // Skip blank lines
            if trimmed.is_empty() {
                i += 1;
                continue;
            }

            // ATX-style heading
            if trimmed.starts_with('#') {
                let level = trimmed.chars().take_while(|&c| c == '#').count();
                if level <= 6 {
                    let rest = &trimmed[level..];
                    let content = if rest.starts_with(' ') || rest.starts_with('\t') {
                        rest.trim_start()
                    } else if rest.is_empty() {
                        rest
                    } else {
                        i += 1;
                        continue;
                    };
                    // Strip trailing #
                    let content = content.trim_end_matches('#').trim_end();
                    let inner = self.parse_inline(content);
                    blocks.push(Token::Header(level as u32, inner));
                    i += 1;
                    continue;
                }
            }

            // Setext-style heading
            if i + 1 < total {
                let next = lines[i + 1].trim();
                if !next.is_empty() && next.chars().all(|c| c == '=') {
                    let inner = self.parse_inline(trimmed);
                    blocks.push(Token::Header(1, inner));
                    i += 2;
                    continue;
                }
                if !next.is_empty() && next.chars().all(|c| c == '-') && next.len() >= 2 {
                    let inner = self.parse_inline(trimmed);
                    blocks.push(Token::Header(2, inner));
                    i += 2;
                    continue;
                }
            }

            // Horizontal rule
            if trimmed.len() >= 3 {
                let first_char = trimmed.chars().next().unwrap();
                if (first_char == '-' || first_char == '*' || first_char == '_') 
                    && trimmed.chars().all(|c| c == first_char || c == ' ') 
                    && trimmed.chars().filter(|&c| c == first_char).count() >= 3 {
                    blocks.push(Token::Rule);
                    i += 1;
                    continue;
                }
            }

            // Fenced code block
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                let fence_char = trimmed.chars().next().unwrap();
                let fence_len = trimmed.chars().take_while(|&c| c == fence_char).count();
                let lang = trimmed[fence_len..].trim();
                let lang = if lang.is_empty() { None } else { Some(lang.to_string()) };

                let mut code_lines = vec![];
                i += 1;
                while i < total {
                    let code_line = lines[i];
                    let code_trimmed = code_line.trim();
                    if code_trimmed.starts_with(&fence_char.to_string().repeat(fence_len)) 
                        && code_trimmed.trim_start_matches(fence_char).trim().is_empty() {
                        i += 1;
                        break;
                    }
                    code_lines.push(code_line);
                    i += 1;
                }
                let code_content = code_lines.join("\n");
                blocks.push(Token::CodeBlock(lang, code_content));
                continue;
            }

            // Indented code block (4 spaces)
            if line.starts_with("    ") || line.starts_with('\t') {
                let mut code_lines = vec![];
                while i < total {
                    let code_line = lines[i];
                    if code_line.trim().is_empty() {
                        code_lines.push("");
                        i += 1;
                    } else if code_line.starts_with("    ") {
                        code_lines.push(&code_line[4..]);
                        i += 1;
                    } else if code_line.starts_with('\t') {
                        code_lines.push(&code_line[1..]);
                        i += 1;
                    } else {
                        break;
                    }
                }
                // Remove trailing blank lines
                while code_lines.last() == Some(&"") {
                    code_lines.pop();
                }
                let code_content = code_lines.join("\n");
                blocks.push(Token::CodeBlock(None, code_content));
                continue;
            }

            // Blockquote
            if trimmed.starts_with('>') {
                let mut bq_lines = vec![];
                while i < total {
                    let bq_line = lines[i];
                    let bq_trimmed = bq_line.trim();
                    if bq_trimmed.starts_with('>') {
                        let content = if bq_trimmed.starts_with("> ") {
                            &bq_trimmed[2..]
                        } else if bq_trimmed.starts_with('>') {
                            &bq_trimmed[1..]
                        } else {
                            bq_trimmed
                        };
                        bq_lines.push(content.to_string());
                        i += 1;
                    } else if bq_trimmed.is_empty() {
                        i += 1;
                        break;
                    } else {
                        // Lazy continuation
                        bq_lines.push(bq_trimmed.to_string());
                        i += 1;
                    }
                }
                let bq_content = bq_lines.join("\n");
                let inner = self.parse_blocks(&bq_content);
                blocks.push(Token::BlockQuote(inner));
                continue;
            }

            // Footnote definition [^label]: content
            if trimmed.starts_with("[^") {
                if let Some(bracket_end) = trimmed.find("]:") {
                    let label = &trimmed[2..bracket_end];
                    let content = trimmed[bracket_end + 2..].trim();
                    let mut def_lines = vec![content.to_string()];
                    i += 1;
                    // Continuation lines (indented)
                    while i < total {
                        let next_line = lines[i];
                        if next_line.starts_with("    ") || next_line.starts_with('\t') {
                            def_lines.push(next_line.trim().to_string());
                            i += 1;
                        } else if next_line.trim().is_empty() {
                            i += 1;
                        } else {
                            break;
                        }
                    }
                    footnote_defs.push((label.to_string(), def_lines.join(" ")));
                    continue;
                }
            }

            // Lists  
            if is_list_marker(trimmed) {
                let (tokens, next_i) = self.parse_list(&lines, i);
                blocks.push(tokens);
                i = next_i;
                continue;
            }

            // Tables
            if i + 1 < total && is_table_separator(lines[i + 1].trim()) {
                let (table, next_i) = self.parse_table(&lines, i);
                blocks.push(table);
                i = next_i;
                continue;
            }

            // HTML block
            if trimmed.starts_with('<') && !trimmed.starts_with("</") {
                // Check if it's a block-level HTML tag
                let tag_end = trimmed[1..].find(|c: char| c == ' ' || c == '>' || c == '/').map(|p| p + 1).unwrap_or(trimmed.len());
                let tag = trimmed[1..tag_end].to_lowercase();
                let block_tags = ["div", "p", "blockquote", "h1", "h2", "h3", "h4", "h5", "h6", 
                                   "ul", "ol", "li", "table", "tr", "td", "th", "thead", "tbody",
                                   "article", "section", "nav", "aside", "header", "footer",
                                   "pre", "figure", "figcaption", "details", "summary"];
                if block_tags.contains(&tag.as_str()) {
                    let mut html_lines = vec![];
                    while i < total && !lines[i].trim().is_empty() {
                        html_lines.push(lines[i]);
                        i += 1;
                    }
                    let html_content = html_lines.join("\n");
                    blocks.push(Token::Html(html_content));
                    continue;
                }
            }

            // Paragraph
            let mut para_lines = vec![];
            while i < total {
                let para_line = lines[i];
                let para_trimmed = para_line.trim();

                if para_trimmed.is_empty() {
                    i += 1;
                    break;
                }

                // Stop if we hit a block element
                if para_trimmed.starts_with('#') 
                    || para_trimmed.starts_with("```") 
                    || para_trimmed.starts_with("~~~")
                    || para_trimmed.starts_with('>')
                    || is_list_marker(para_trimmed) {
                    break;
                }

                // Check for setext heading
                if i + 1 < total {
                    let next = lines[i + 1].trim();
                    if !next.is_empty() && (next.chars().all(|c| c == '=') || (next.chars().all(|c| c == '-') && next.len() >= 2)) {
                        break;
                    }
                }

                // Check for HR
                if para_trimmed.len() >= 3 {
                    let first_char = para_trimmed.chars().next().unwrap();
                    if (first_char == '-' || first_char == '*' || first_char == '_') 
                        && para_trimmed.chars().all(|c| c == first_char || c == ' ') 
                        && para_trimmed.chars().filter(|&c| c == first_char).count() >= 3 {
                        break;
                    }
                }

                para_lines.push(para_trimmed);
                i += 1;
            }

            if !para_lines.is_empty() {
                // Join paragraph lines, handling hard breaks
                let mut para_text = String::new();
                for (j, pl) in para_lines.iter().enumerate() {
                    if j > 0 {
                        // Check for hard break (trailing 2+ spaces or backslash)
                        if para_lines[j-1].ends_with("  ") || para_lines[j-1].ends_with('\\') {
                            para_text.push('\n'); // Will be converted to HardBreak
                        } else {
                            para_text.push(' ');
                        }
                    }
                    para_text.push_str(pl);
                }
                let inner = self.parse_inline(&para_text);
                if !inner.is_empty() {
                    blocks.push(Token::Paragraph(inner));
                }
            }
        }

        // Process footnote definitions
        if !footnote_defs.is_empty() {
            // We need to assign numbers to footnotes
            // For now, just store them for later resolution
            // They'll be referenced by label in the text
        }

        blocks
    }

    fn parse_list(&mut self, lines: &[&str], start_i: usize) -> (Token, usize) {
        let first_line = lines[start_i].trim();
        let is_ordered = first_line.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);

        let mut items: Vec<ListItem> = vec![];
        let mut i = start_i;

        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim();

            if trimmed.is_empty() {
                i += 1;
                continue;
            }

            if !is_list_marker(trimmed) {
                break;
            }

            // Extract content after the marker
            let content_start = get_list_content(trimmed);
            let mut item_text = trimmed[content_start..].to_string();
            i += 1;

            // Continuation lines
            while i < lines.len() {
                let next = lines[i];
                let next_trimmed = next.trim();
                if next_trimmed.is_empty() {
                    i += 1;
                    continue;
                }
                // Indented continuation
                if next.starts_with("    ") || next.starts_with('\t') {
                    item_text.push(' ');
                    item_text.push_str(next_trimmed);
                    i += 1;
                } else if is_list_marker(next_trimmed) {
                    break;
                } else {
                    break;
                }
            }

            // Check for task item
            let (is_task, cleaned_text) = if item_text.starts_with("[ ] ") {
                (Some(false), item_text[4..].to_string())
            } else if item_text.starts_with("[x] ") || item_text.starts_with("[X] ") {
                (Some(true), item_text[4..].to_string())
            } else {
                (None, item_text)
            };

            let inner = self.parse_inline(&cleaned_text);
            items.push(ListItem { is_task, content: inner });
        }

        (Token::List(is_ordered, items), i)
    }

    fn parse_table(&mut self, lines: &[&str], start_i: usize) -> (Token, usize) {
        // Parse header row
        let header_line = lines[start_i].trim();
        let sep_line = lines[start_i + 1].trim();

        // Parse alignments from separator
        let alignments: Vec<Alignment> = sep_line
            .trim_matches('|')
            .split('|')
            .map(|cell| {
                let cell = cell.trim();
                if cell.starts_with(':') && cell.ends_with(':') {
                    Alignment::Center
                } else if cell.ends_with(':') {
                    Alignment::Right
                } else if cell.starts_with(':') {
                    Alignment::Left
                } else {
                    Alignment::None
                }
            })
            .collect();

        // Parse header cells
        let header_cells: Vec<Vec<Token>> = parse_table_row(header_line)
            .iter()
            .map(|cell| self.parse_inline(cell))
            .collect();

        let mut rows = vec![header_cells];
        let mut i = start_i + 2;

        // Parse data rows
        while i < lines.len() {
            let row_line = lines[i].trim();
            if row_line.is_empty() || !row_line.contains('|') {
                break;
            }
            let row_cells: Vec<Vec<Token>> = parse_table_row(row_line)
                .iter()
                .map(|cell| self.parse_inline(cell))
                .collect();
            rows.push(row_cells);
            i += 1;
        }

        (Token::Table(rows, alignments), i)
    }

    fn parse_inline(&self, text: &str) -> Vec<Token> {
        let mut result = vec![];
        let chars: Vec<char> = text.chars().collect();
        let mut pos = 0;
        let mut current_str = String::new();

        // Track footnote references we encounter
        let mut footnote_map: std::collections::HashMap<String, u32> = std::collections::HashMap::new();
        let mut footnote_counter: u32 = 0;

        while pos < chars.len() {
            let c = chars[pos];

            // Check for footnote reference [^label]
            if c == '[' && pos + 1 < chars.len() && chars[pos + 1] == '^' {
                if let Some(bracket_end) = find_bracket_end(&chars, pos) {
                    let label = chars[pos+2..bracket_end].iter().collect::<String>();
                    if !label.is_empty() {
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        // Assign a footnote number
                        let num = if let Some(&n) = footnote_map.get(&label) {
                            n
                        } else {
                            footnote_counter += 1;
                            footnote_map.insert(label.clone(), footnote_counter);
                            footnote_counter
                        };
                        result.push(Token::Footnote(num));
                        pos = bracket_end + 1;
                        continue;
                    }
                }
            }

            // Links [text](url)
            if c == '[' {
                if let Some((link_token, end_pos)) = try_parse_link(&chars, pos, self) {
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(link_token);
                    pos = end_pos;
                    continue;
                }
            }

            // Images ![alt](url)
            if c == '!' && pos + 1 < chars.len() && chars[pos + 1] == '[' {
                if let Some((img_token, end_pos)) = try_parse_image(&chars, pos) {
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(img_token);
                    pos = end_pos;
                    continue;
                }
            }

            // Inline code
            if c == '`' {
                let backtick_count = chars[pos..].iter().take_while(|&&ch| ch == '`').count();
                let close_marker: String = std::iter::repeat('`').take(backtick_count).collect();
                let start = pos + backtick_count;
                let remaining: String = chars[start..].iter().collect();
                if let Some(close_pos) = remaining.find(&close_marker) {
                    let code_content = &remaining[..close_pos];
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(Token::Code(code_content.trim().to_string()));
                    pos = start + close_pos + backtick_count;
                    continue;
                }
            }

            // Strong/Em with * or _
            if (c == '*' || c == '_') {
                let delim_count = chars[pos..].iter().take_while(|&&ch| ch == c).count();

                if delim_count >= 2 {
                    // Strong
                    let start = pos + delim_count;
                    let delim_str: String = std::iter::repeat(c).take(delim_count).collect();
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = find_delim_close(&remaining, &delim_str) {
                        let inner_text = &remaining[..close_pos];
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        let inner = self.parse_inline(inner_text);
                        if delim_count >= 3 {
                            result.push(Token::Strong(vec![Token::Em(inner)]));
                        } else {
                            result.push(Token::Strong(inner));
                        }
                        pos = start + close_pos + delim_count;
                        continue;
                    }
                } else if delim_count == 1 {
                    // Em
                    let start = pos + 1;
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = find_delim_close(&remaining, &c.to_string()) {
                        let inner_text = &remaining[..close_pos];
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        let inner = self.parse_inline(inner_text);
                        result.push(Token::Em(inner));
                        pos = start + close_pos + 1;
                        continue;
                    }
                }
            }

            // Strikethrough ~~text~~
            if c == '~' && pos + 1 < chars.len() && chars[pos + 1] == '~' {
                let start = pos + 2;
                let remaining: String = chars[start..].iter().collect();
                if let Some(close_pos) = remaining.find("~~") {
                    let inner_text = &remaining[..close_pos];
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    let inner = self.parse_inline(inner_text);
                    result.push(Token::Strikethrough(inner));
                    pos = start + close_pos + 2;
                    continue;
                }
            }

            // Superscript ^text^ (only when enabled)
            if self.superscript_enabled && c == '^' {
                let start = pos + 1;
                if start < chars.len() && chars[start] != ' ' {
                    let remaining: String = chars[start..].iter().collect();
                    // Find next ^ (not preceded by space)
                    if let Some(close_pos) = remaining.find('^') {
                        let inner_text = &remaining[..close_pos];
                        if !inner_text.contains(' ') {
                            if !current_str.is_empty() {
                                result.push(Token::Str(current_str.clone()));
                                current_str.clear();
                            }
                            let inner = self.parse_inline(inner_text);
                            result.push(Token::Superscript(inner));
                            pos = start + close_pos + 1;
                            continue;
                        }
                    }
                }
            }

            // Subscript ~text~ (only when superscript mode enabled, single ~)
            if self.superscript_enabled && c == '~' && (pos + 1 >= chars.len() || chars[pos + 1] != '~') {
                let start = pos + 1;
                if start < chars.len() && chars[start] != ' ' {
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = remaining.find('~') {
                        let inner_text = &remaining[..close_pos];
                        if !inner_text.contains(' ') && !inner_text.contains('~') {
                            if !current_str.is_empty() {
                                result.push(Token::Str(current_str.clone()));
                                current_str.clear();
                            }
                            let inner = self.parse_inline(inner_text);
                            result.push(Token::Subscript(inner));
                            pos = start + close_pos + 1;
                            continue;
                        }
                    }
                }
            }

            // Hard break (two spaces + newline, or backslash + newline)
            if c == '\n' {
                if !current_str.is_empty() {
                    result.push(Token::Str(current_str.clone()));
                    current_str.clear();
                }
                result.push(Token::SoftBreak);
                pos += 1;
                continue;
            }

            // Check for hard break marker (backslash before newline or two spaces)
            if c == '\\' && pos + 1 < chars.len() && chars[pos + 1] == '\n' {
                if !current_str.is_empty() {
                    result.push(Token::Str(current_str.clone()));
                    current_str.clear();
                }
                result.push(Token::HardBreak);
                pos += 2;
                continue;
            }

            // Escape character
            if c == '\\' && pos + 1 < chars.len() {
                let escaped = chars[pos + 1];
                current_str.push(escaped);
                pos += 2;
                continue;
            }

            current_str.push(c);
            pos += 1;
        }

        if !current_str.is_empty() {
            result.push(Token::Str(current_str));
        }

        result
    }
}

fn is_list_marker(line: &str) -> bool {
    if line.is_empty() {
        return false;
    }
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return line.len() >= 2 && (line.chars().nth(1) == Some(' ') || line.chars().nth(1) == Some('\t'));
    }
    // Ordered list
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    if !digits.is_empty() {
        let after_digits = &line[digits.len()..];
        return after_digits.starts_with(". ") || after_digits.starts_with(".\t") || after_digits == ".";
    }
    false
}

fn get_list_content(line: &str) -> usize {
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return 2;
    }
    // Ordered
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    digits.len() + 2 // digit(s) + ". "
}

fn is_table_separator(line: &str) -> bool {
    if !line.contains('|') && !line.contains('-') {
        return false;
    }
    let cells: Vec<&str> = line.trim_matches('|').split('|').collect();
    if cells.is_empty() {
        return false;
    }
    cells.iter().all(|cell| {
        let c = cell.trim();
        !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':' || ch == ' ')
    })
}

fn parse_table_row(line: &str) -> Vec<String> {
    line.trim_matches('|')
        .split('|')
        .map(|cell| cell.trim().to_string())
        .collect()
}

fn find_bracket_end(chars: &[char], start: usize) -> Option<usize> {
    assert_eq!(chars[start], '[');
    let mut depth = 0;
    let mut pos = start;
    while pos < chars.len() {
        if chars[pos] == '[' {
            depth += 1;
        } else if chars[pos] == ']' {
            depth -= 1;
            if depth == 0 {
                return Some(pos);
            }
        }
        pos += 1;
    }
    None
}

fn find_delim_close(text: &str, delim: &str) -> Option<usize> {
    text.find(delim)
}

fn try_parse_link(chars: &[char], start: usize, parser: &MarkdownParser) -> Option<(Token, usize)> {
    // [text](url "title") or [text](url)
    let bracket_end = find_bracket_end(chars, start)?;

    if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' {
        return None;
    }

    let paren_start = bracket_end + 1;
    let paren_end = find_paren_end(chars, paren_start)?;

    let text: String = chars[start+1..bracket_end].iter().collect();
    let url_part: String = chars[paren_start+1..paren_end].iter().collect();

    let (url, title) = parse_url_title(&url_part);
    let inner = parser.parse_inline(&text);

    Some((Token::Link(url, title, inner), paren_end + 1))
}

fn try_parse_image(chars: &[char], start: usize) -> Option<(Token, usize)> {
    // ![alt](url "title")
    assert_eq!(chars[start], '!');
    if start + 1 >= chars.len() || chars[start + 1] != '[' {
        return None;
    }

    let bracket_end = find_bracket_end(chars, start + 1)?;

    if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' {
        return None;
    }

    let paren_start = bracket_end + 1;
    let paren_end = find_paren_end(chars, paren_start)?;

    let alt: String = chars[start+2..bracket_end].iter().collect();
    let url_part: String = chars[paren_start+1..paren_end].iter().collect();

    let (url, title) = parse_url_title(&url_part);

    Some((Token::Image(url, title, alt), paren_end + 1))
}

fn find_paren_end(chars: &[char], start: usize) -> Option<usize> {
    assert_eq!(chars[start], '(');
    let mut depth = 0;
    let mut in_str = false;
    let mut str_char = '"';
    let mut pos = start;

    while pos < chars.len() {
        let c = chars[pos];
        if in_str {
            if c == str_char {
                in_str = false;
            } else if c == '\\' {
                pos += 1; // skip escaped char
            }
        } else {
            match c {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(pos);
                    }
                }
                '"' | '\'' => {
                    in_str = true;
                    str_char = c;
                }
                _ => {}
            }
        }
        pos += 1;
    }
    None
}

fn parse_url_title(s: &str) -> (String, String) {
    let s = s.trim();
    // Check for title after URL
    if let Some(title_start) = s.rfind('"') {
        if let Some(title_begin) = s[..title_start].rfind('"') {
            // Make sure there's a space before the title
            let url_part = s[..title_begin].trim();
            let title = &s[title_begin+1..title_start];
            return (url_part.to_string(), title.to_string());
        }
    }
    (s.to_string(), String::new())
}

/// Parse markdown, handling footnotes by collecting them
pub fn parse_with_footnotes(input: &str, superscript: bool) -> (Vec<Token>, Vec<(String, Vec<Token>)>) {
    // First, extract footnote definitions
    let mut footnote_defs: Vec<(String, String)> = vec![];
    let mut clean_lines: Vec<String> = vec![];

    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();
        if trimmed.starts_with("[^") {
            if let Some(bracket_end) = trimmed.find("]:") {
                let label = &trimmed[2..bracket_end];
                let content = trimmed[bracket_end + 2..].trim();
                let mut def_lines = vec![content.to_string()];
                i += 1;
                while i < lines.len() {
                    let next = lines[i];
                    if next.trim().is_empty() {
                        i += 1;
                    } else if next.starts_with("    ") || next.starts_with('\t') {
                        def_lines.push(next.trim().to_string());
                        i += 1;
                    } else {
                        break;
                    }
                }
                footnote_defs.push((label.to_string(), def_lines.join(" ")));
                continue;
            }
        }
        clean_lines.push(line.to_string());
        i += 1;
    }

    let clean_text = clean_lines.join("\n");
    let mut parser = MarkdownParser::new(&clean_text, superscript);
    let tokens = parser.parse_blocks(&clean_text);

