            // Continuation lines
            while i < lines.len() {
                let next = lines[i];
                let next_trimmed = next.trim();
                if next_trimmed.is_empty() {
                    i += 1;
                    continue;
                }
                // Indented continuation
                if next.starts_with("    ") || next.starts_with('\t') {
                    item_text.push(' ');
                    item_text.push_str(next_trimmed);
                    i += 1;
                } else if is_list_marker(next_trimmed) {
                    break;
                } else {
                    break;
                }
            }

            // Check for task item
            let (is_task, cleaned_text) = if item_text.starts_with("[ ] ") {
                (Some(false), item_text[4..].to_string())
            } else if item_text.starts_with("[x] ") || item_text.starts_with("[X] ") {
                (Some(true), item_text[4..].to_string())
            } else {
                (None, item_text)
            };

            let inner = self.parse_inline(&cleaned_text);
            items.push(ListItem { is_task, content: inner });
        }

        (Token::List(is_ordered, items), i)
    }

    fn parse_table(&mut self, lines: &[&str], start_i: usize) -> (Token, usize) {
        // Parse header row
        let header_line = lines[start_i].trim();
        let sep_line = lines[start_i + 1].trim();

        // Parse alignments from separator
        let alignments: Vec<Alignment> = sep_line
            .trim_matches('|')
            .split('|')
            .map(|cell| {
                let cell = cell.trim();
                if cell.starts_with(':') && cell.ends_with(':') {
                    Alignment::Center
                } else if cell.ends_with(':') {
                    Alignment::Right
                } else if cell.starts_with(':') {
                    Alignment::Left
                } else {
                    Alignment::None
                }
            })
            .collect();

        // Parse header cells
        let header_cells: Vec<Vec<Token>> = parse_table_row(header_line)
            .iter()
            .map(|cell| self.parse_inline(cell))
            .collect();

        let mut rows = vec![header_cells];
        let mut i = start_i + 2;

        // Parse data rows
        while i < lines.len() {
            let row_line = lines[i].trim();
            if row_line.is_empty() || !row_line.contains('|') {
                break;
            }
            let row_cells: Vec<Vec<Token>> = parse_table_row(row_line)
                .iter()
                .map(|cell| self.parse_inline(cell))
                .collect();
            rows.push(row_cells);
            i += 1;
        }

        (Token::Table(rows, alignments), i)
    }

    fn parse_inline(&self, text: &str) -> Vec<Token> {
        let mut result = vec![];
        let chars: Vec<char> = text.chars().collect();
        let mut pos = 0;
        let mut current_str = String::new();

        // Track footnote references we encounter
        let mut footnote_map: std::collections::HashMap<String, u32> = std::collections::HashMap::new();
        let mut footnote_counter: u32 = 0;

        while pos < chars.len() {
            let c = chars[pos];

            // Check for footnote reference [^label]
            if c == '[' && pos + 1 < chars.len() && chars[pos + 1] == '^' {
                if let Some(bracket_end) = find_bracket_end(&chars, pos) {
                    let label = chars[pos+2..bracket_end].iter().collect::<String>();
                    if !label.is_empty() {
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        // Assign a footnote number
                        let num = if let Some(&n) = footnote_map.get(&label) {
                            n
                        } else {
                            footnote_counter += 1;
                            footnote_map.insert(label.clone(), footnote_counter);
                            footnote_counter
                        };
                        result.push(Token::Footnote(num));
                        pos = bracket_end + 1;
                        continue;
                    }
                }
            }

            // Links [text](url)
            if c == '[' {
                if let Some((link_token, end_pos)) = try_parse_link(&chars, pos, self) {
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(link_token);
                    pos = end_pos;
                    continue;
                }
            }

            // Images ![alt](url)
            if c == '!' && pos + 1 < chars.len() && chars[pos + 1] == '[' {
                if let Some((img_token, end_pos)) = try_parse_image(&chars, pos) {
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(img_token);
                    pos = end_pos;
                    continue;
                }
            }

            // Inline code
            if c == '`' {
                let backtick_count = chars[pos..].iter().take_while(|&&ch| ch == '`').count();
                let close_marker: String = std::iter::repeat('`').take(backtick_count).collect();
                let start = pos + backtick_count;
                let remaining: String = chars[start..].iter().collect();
                if let Some(close_pos) = remaining.find(&close_marker) {
                    let code_content = &remaining[..close_pos];
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    result.push(Token::Code(code_content.trim().to_string()));
                    pos = start + close_pos + backtick_count;
                    continue;
                }
            }

            // Strong/Em with * or _
            if (c == '*' || c == '_') {
                let delim_count = chars[pos..].iter().take_while(|&&ch| ch == c).count();

                if delim_count >= 2 {
                    // Strong
                    let start = pos + delim_count;
                    let delim_str: String = std::iter::repeat(c).take(delim_count).collect();
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = find_delim_close(&remaining, &delim_str) {
                        let inner_text = &remaining[..close_pos];
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        let inner = self.parse_inline(inner_text);
                        if delim_count >= 3 {
                            result.push(Token::Strong(vec![Token::Em(inner)]));
                        } else {
                            result.push(Token::Strong(inner));
                        }
                        pos = start + close_pos + delim_count;
                        continue;
                    }
                } else if delim_count == 1 {
                    // Em
                    let start = pos + 1;
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = find_delim_close(&remaining, &c.to_string()) {
                        let inner_text = &remaining[..close_pos];
                        if !current_str.is_empty() {
                            result.push(Token::Str(current_str.clone()));
                            current_str.clear();
                        }
                        let inner = self.parse_inline(inner_text);
                        result.push(Token::Em(inner));
                        pos = start + close_pos + 1;
                        continue;
                    }
                }
            }

            // Strikethrough ~~text~~
            if c == '~' && pos + 1 < chars.len() && chars[pos + 1] == '~' {
                let start = pos + 2;
                let remaining: String = chars[start..].iter().collect();
                if let Some(close_pos) = remaining.find("~~") {
                    let inner_text = &remaining[..close_pos];
                    if !current_str.is_empty() {
                        result.push(Token::Str(current_str.clone()));
                        current_str.clear();
                    }
                    let inner = self.parse_inline(inner_text);
                    result.push(Token::Strikethrough(inner));
                    pos = start + close_pos + 2;
                    continue;
                }
            }

            // Superscript ^text^ (only when enabled)
            if self.superscript_enabled && c == '^' {
                let start = pos + 1;
                if start < chars.len() && chars[start] != ' ' {
                    let remaining: String = chars[start..].iter().collect();
                    // Find next ^ (not preceded by space)
                    if let Some(close_pos) = remaining.find('^') {
                        let inner_text = &remaining[..close_pos];
                        if !inner_text.contains(' ') {
                            if !current_str.is_empty() {
                                result.push(Token::Str(current_str.clone()));
                                current_str.clear();
                            }
                            let inner = self.parse_inline(inner_text);
                            result.push(Token::Superscript(inner));
                            pos = start + close_pos + 1;
                            continue;
                        }
                    }
                }
            }

            // Subscript ~text~ (only when superscript mode enabled, single ~)
            if self.superscript_enabled && c == '~' && (pos + 1 >= chars.len() || chars[pos + 1] != '~') {
                let start = pos + 1;
                if start < chars.len() && chars[start] != ' ' {
                    let remaining: String = chars[start..].iter().collect();
                    if let Some(close_pos) = remaining.find('~') {
                        let inner_text = &remaining[..close_pos];
                        if !inner_text.contains(' ') && !inner_text.contains('~') {
                            if !current_str.is_empty() {
                                result.push(Token::Str(current_str.clone()));
                                current_str.clear();
                            }
                            let inner = self.parse_inline(inner_text);
                            result.push(Token::Subscript(inner));
                            pos = start + close_pos + 1;
                            continue;
                        }
                    }
                }
            }

            // Hard break (two spaces + newline, or backslash + newline)
            if c == '\n' {
                if !current_str.is_empty() {
                    result.push(Token::Str(current_str.clone()));
                    current_str.clear();
                }
                result.push(Token::SoftBreak);
                pos += 1;
                continue;
            }

            // Check for hard break marker (backslash before newline or two spaces)
            if c == '\\' && pos + 1 < chars.len() && chars[pos + 1] == '\n' {
                if !current_str.is_empty() {
                    result.push(Token::Str(current_str.clone()));
                    current_str.clear();
                }
                result.push(Token::HardBreak);
                pos += 2;
                continue;
            }

            // Escape character
            if c == '\\' && pos + 1 < chars.len() {
                let escaped = chars[pos + 1];
                current_str.push(escaped);
                pos += 2;
                continue;
            }

            current_str.push(c);
            pos += 1;
        }

        if !current_str.is_empty() {
            result.push(Token::Str(current_str));
        }

        result
    }
}

fn is_list_marker(line: &str) -> bool {
    if line.is_empty() {
        return false;
    }
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return line.len() >= 2 && (line.chars().nth(1) == Some(' ') || line.chars().nth(1) == Some('\t'));
    }
    // Ordered list
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    if !digits.is_empty() {
        let after_digits = &line[digits.len()..];
        return after_digits.starts_with(". ") || after_digits.starts_with(".\t") || after_digits == ".";
    }
    false
}

fn get_list_content(line: &str) -> usize {
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return 2;
    }
    // Ordered
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    digits.len() + 2 // digit(s) + ". "
}

fn is_table_separator(line: &str) -> bool {
    if !line.contains('|') && !line.contains('-') {
        return false;
    }
    let cells: Vec<&str> = line.trim_matches('|').split('|').collect();
    if cells.is_empty() {
        return false;
    }
    cells.iter().all(|cell| {
        let c = cell.trim();
        !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':' || ch == ' ')
    })
}

fn parse_table_row(line: &str) -> Vec<String> {
    line.trim_matches('|')
        .split('|')
        .map(|cell| cell.trim().to_string())
        .collect()
}

fn find_bracket_end(chars: &[char], start: usize) -> Option<usize> {
    assert_eq!(chars[start], '[');
    let mut depth = 0;
    let mut pos = start;
    while pos < chars.len() {
        if chars[pos] == '[' {
            depth += 1;
        } else if chars[pos] == ']' {
            depth -= 1;
            if depth == 0 {
                return Some(pos);
            }
        }
        pos += 1;
    }
    None
}

fn find_delim_close(text: &str, delim: &str) -> Option<usize> {
    text.find(delim)
}

fn try_parse_link(chars: &[char], start: usize, parser: &MarkdownParser) -> Option<(Token, usize)> {
    // [text](url "title") or [text](url)
    let bracket_end = find_bracket_end(chars, start)?;

    if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' {
        return None;
    }

    let paren_start = bracket_end + 1;
    let paren_end = find_paren_end(chars, paren_start)?;

    let text: String = chars[start+1..bracket_end].iter().collect();
    let url_part: String = chars[paren_start+1..paren_end].iter().collect();

    let (url, title) = parse_url_title(&url_part);
    let inner = parser.parse_inline(&text);

    Some((Token::Link(url, title, inner), paren_end + 1))
}

fn try_parse_image(chars: &[char], start: usize) -> Option<(Token, usize)> {
    // ![alt](url "title")
    assert_eq!(chars[start], '!');
    if start + 1 >= chars.len() || chars[start + 1] != '[' {
        return None;
    }

    let bracket_end = find_bracket_end(chars, start + 1)?;

    if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' {
        return None;
    }

    let paren_start = bracket_end + 1;
    let paren_end = find_paren_end(chars, paren_start)?;

    let alt: String = chars[start+2..bracket_end].iter().collect();
    let url_part: String = chars[paren_start+1..paren_end].iter().collect();

    let (url, title) = parse_url_title(&url_part);

    Some((Token::Image(url, title, alt), paren_end + 1))
}

fn find_paren_end(chars: &[char], start: usize) -> Option<usize> {
    assert_eq!(chars[start], '(');
    let mut depth = 0;
    let mut in_str = false;
    let mut str_char = '"';
    let mut pos = start;

    while pos < chars.len() {
        let c = chars[pos];
        if in_str {
            if c == str_char {
                in_str = false;
            } else if c == '\\' {
                pos += 1; // skip escaped char
            }
        } else {
            match c {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some(pos);
                    }
                }
                '"' | '\'' => {
                    in_str = true;
                    str_char = c;
                }
                _ => {}
            }
        }
        pos += 1;
    }
    None
}

fn parse_url_title(s: &str) -> (String, String) {
    let s = s.trim();
    // Check for title after URL
    if let Some(title_start) = s.rfind('"') {
        if let Some(title_begin) = s[..title_start].rfind('"') {
            // Make sure there's a space before the title
            let url_part = s[..title_begin].trim();
            let title = &s[title_begin+1..title_start];
            return (url_part.to_string(), title.to_string());
        }
    }
    (s.to_string(), String::new())
}

/// Parse markdown, handling footnotes by collecting them
pub fn parse_with_footnotes(input: &str, superscript: bool) -> (Vec<Token>, Vec<(String, Vec<Token>)>) {
    // First, extract footnote definitions
    let mut footnote_defs: Vec<(String, String)> = vec![];
    let mut clean_lines: Vec<String> = vec![];

    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();
        if trimmed.starts_with("[^") {
            if let Some(bracket_end) = trimmed.find("]:") {
                let label = &trimmed[2..bracket_end];
                let content = trimmed[bracket_end + 2..].trim();
                let mut def_lines = vec![content.to_string()];
                i += 1;
                while i < lines.len() {
                    let next = lines[i];
                    if next.trim().is_empty() {
                        i += 1;
                    } else if next.starts_with("    ") || next.starts_with('\t') {
                        def_lines.push(next.trim().to_string());
                        i += 1;
                    } else {
                        break;
                    }
                }
                footnote_defs.push((label.to_string(), def_lines.join(" ")));
                continue;
            }
        }
        clean_lines.push(line.to_string());
        i += 1;
    }

    let clean_text = clean_lines.join("\n");
    let mut parser = MarkdownParser::new(&clean_text, superscript);
    let tokens = parser.parse_blocks(&clean_text);

    // Parse footnote content
    let parsed_footnotes: Vec<(String, Vec<Token>)> = footnote_defs.iter()
        .map(|(label, content)| {
            let parsed = parser.parse_blocks(content);
            (label.clone(), parsed)
        })
        .collect();

    (tokens, parsed_footnotes)
}
RUST_EOF

