}

#[derive(Debug, Clone)]
pub struct ListItem {
    pub is_task: Option<bool>,  // None=not task, Some(true)=checked, Some(false)=unchecked
    pub tokens: Vec<Token>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum Alignment {
    Left,
    Center,
    Right,
    None,
}

pub struct Parser {
    superscript: bool,
}

impl Parser {
    pub fn new(superscript: bool) -> Self {
        Parser { superscript }
    }

    pub fn parse(&self, text: &str) -> Vec<Token> {
        // Extract footnote definitions first
        let (clean_text, fn_defs) = extract_footnote_defs(text);
        let mut tokens = self.parse_blocks(&clean_text);

        // Add footnote definitions at the end
        for (label, content) in fn_defs {
            let fn_content = self.parse_blocks(&content);
            tokens.push(Token::FootnoteDef(label, fn_content));
        }

        tokens
    }

    fn parse_blocks(&self, text: &str) -> Vec<Token> {
        let lines: Vec<&str> = text.lines().collect();
        let mut tokens = Vec::new();
        let mut i = 0;

        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim();

            if trimmed.is_empty() {
                i += 1;
                continue;
            }

            // ATX heading
            if let Some(level) = atx_heading_level(trimmed) {
                let rest = trimmed[level..].trim_start_matches(' ').trim_start_matches('\t');
                let rest = rest.trim_end_matches('#').trim_end();
                let inner = self.parse_inline(rest);
                tokens.push(Token::Header(level as u32, inner));
                i += 1;
                continue;
            }

            // Setext heading
            if i + 1 < lines.len() {
                let next = lines[i + 1].trim();
                if !trimmed.is_empty() && !next.is_empty() && next.chars().all(|c| c == '=') && next.len() >= 2 {
                    let inner = self.parse_inline(trimmed);
                    tokens.push(Token::Header(1, inner));
                    i += 2;
                    continue;
                }
                if !trimmed.is_empty() && !next.is_empty() && next.chars().all(|c| c == '-') && next.len() >= 2 {
                    // Check if it might be a horizontal rule
                    if !is_horizontal_rule(next) {
                        let inner = self.parse_inline(trimmed);
                        tokens.push(Token::Header(2, inner));
                        i += 2;
                        continue;
                    }
                }
            }

            // Horizontal rule
            if is_horizontal_rule(trimmed) {
                tokens.push(Token::Rule);
                i += 1;
                continue;
            }

            // Fenced code block
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                let fence_char = trimmed.chars().next().unwrap();
                let fence_len = count_fence(trimmed, fence_char);
                let info = trimmed[fence_len..].trim().to_string();
                let lang = if info.is_empty() { None } else { Some(info) };

                let mut code_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let cline = lines[i];
                    let ctrimmed = cline.trim();
                    if ctrimmed.starts_with(&fence_char.to_string().repeat(fence_len)) {
                        let rest_after_fence = &ctrimmed[fence_len..];
                        if rest_after_fence.trim().is_empty() {
                            i += 1;
                            break;
                        }
                    }
                    code_lines.push(cline);
                    i += 1;
                }
                let code = code_lines.join("\n");
                tokens.push(Token::CodeBlock(lang, code));
                continue;
            }

            // Indented code block
            if line.starts_with("    ") || line.starts_with('\t') {
                // Make sure it's not a list continuation
                let mut code_lines = Vec::new();
                while i < lines.len() {
                    let cline = lines[i];
                    if cline.trim().is_empty() {
                        code_lines.push("");
                        i += 1;
                    } else if cline.starts_with("    ") {
                        code_lines.push(&cline[4..]);
                        i += 1;
                    } else if cline.starts_with('\t') {
                        code_lines.push(&cline[1..]);
                        i += 1;
                    } else {
                        break;
                    }
                }
                // Remove trailing blank lines
                while code_lines.last() == Some(&"") {
                    code_lines.pop();
                }
                let code = code_lines.join("\n");
                if !code.is_empty() {
                    tokens.push(Token::CodeBlock(None, code));
                }
                continue;
            }

            // Blockquote
            if trimmed.starts_with('>') {
                let mut bq_lines = Vec::new();
                while i < lines.len() {
                    let bline = lines[i];
                    let btrimmed = bline.trim();
                    if btrimmed.starts_with('>') {
                        let content = if btrimmed.len() > 1 && (btrimmed.chars().nth(1) == Some(' ') || btrimmed.chars().nth(1) == Some('\t')) {
                            &btrimmed[2..]
                        } else {
                            &btrimmed[1..]
                        };
                        bq_lines.push(content.to_string());
                        i += 1;
                    } else if btrimmed.is_empty() {
                        bq_lines.push(String::new());
                        i += 1;
                        // Check if next non-empty line continues blockquote
                        let j = i;
                        if j < lines.len() && lines[j].trim().starts_with('>') {
                            continue;
                        }
                        break;
                    } else {
                        break;
                    }
                }
                let bq_text = bq_lines.join("\n");
                let inner = self.parse_blocks(&bq_text);
                tokens.push(Token::BlockQuote(inner));
                continue;
            }

            // List
            if is_list_marker(trimmed) {
                let (list_token, next_i) = self.parse_list(lines, i);
                tokens.push(list_token);
                i = next_i;
                continue;
            }

            // Table (pipe table)
            if i + 1 < lines.len() && is_table_separator(lines[i + 1].trim()) {
                let (table_token, next_i) = self.parse_table(lines, i);
                tokens.push(table_token);
                i = next_i;
                continue;
            }

            // HTML block
            if is_block_html(trimmed) {
                let mut html_lines = vec![line.to_string()];
                i += 1;
                while i < lines.len() && !lines[i].trim().is_empty() {
                    html_lines.push(lines[i].to_string());
                    i += 1;
                }
                tokens.push(Token::Html(html_lines.join("\n")));
                continue;
            }

            // Paragraph
            let mut para_lines = Vec::new();
            while i < lines.len() {
                let pline = lines[i];
                let ptrimmed = pline.trim();

                if ptrimmed.is_empty() {
                    i += 1;
                    break;
                }

                // Check for block-level interrupts
                if atx_heading_level(ptrimmed).is_some() { break; }
                if ptrimmed.starts_with("```") || ptrimmed.starts_with("~~~") { break; }
                if ptrimmed.starts_with('>') { break; }
                if is_list_marker(ptrimmed) { break; }
                if is_horizontal_rule(ptrimmed) { break; }

                // Check for setext heading
                if i + 1 < lines.len() {
                    let next = lines[i + 1].trim();
                    if !next.is_empty() && next.chars().all(|c| c == '=') && next.len() >= 2 { break; }
                    if !next.is_empty() && next.chars().all(|c| c == '-') && next.len() >= 2 && !is_horizontal_rule(next) { break; }
                }

                para_lines.push(ptrimmed);
                i += 1;
            }

            if !para_lines.is_empty() {
                // Join paragraph lines
                let mut para_text = String::new();
                for (j, pl) in para_lines.iter().enumerate() {
                    if j > 0 {
                        if para_lines[j-1].ends_with("  ") {
                            para_text.push('\x01'); // hard break marker
                        } else if para_lines[j-1].ends_with('\\') {
                            // Remove backslash, add hard break
                            para_text.pop();
                            para_text.push('\x01');
                        } else {
                            para_text.push(' ');
                        }
                    }
                    para_text.push_str(pl);
                }
                let inner = self.parse_inline(&para_text);
                if !inner.is_empty() {
                    tokens.push(Token::Paragraph(inner));
                }
            }
        }

        tokens
    }

    fn parse_list(&self, lines: &[&str], start: usize) -> (Token, usize) {
        let first_line = lines[start].trim();
        let ordered = first_line.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);

        let mut items = Vec::new();
        let mut i = start;

        while i < lines.len() {
            let line = lines[i];
            let trimmed = line.trim();

            if trimmed.is_empty() {
                i += 1;
                continue;
            }

            if !is_list_marker(trimmed) {
                // If we have no items yet, break
                if items.is_empty() { break; }
                // Otherwise might be continuation - but we'll be conservative
                break;
            }

            let content_start = list_marker_len(trimmed);
            let mut item_text = trimmed[content_start..].to_string();
            i += 1;

            // Gather continuation lines
            while i < lines.len() {
                let nline = lines[i];
                let ntrimmed = nline.trim();

                if ntrimmed.is_empty() {
                    i += 1;
                    // Lookahead to see if next non-empty line continues this item
                    let j = i;
                    if j < lines.len() && (lines[j].starts_with("    ") || lines[j].starts_with('\t')) {
                        continue;
                    }
                    break;
                }

                // Indented continuation
                if nline.starts_with("    ") || nline.starts_with('\t') {
                    item_text.push('\n');
                    item_text.push_str(ntrimmed);
                    i += 1;
                } else if is_list_marker(ntrimmed) {
                    break;
                } else {
                    // Lazy continuation within same ordered list
                    item_text.push(' ');
                    item_text.push_str(ntrimmed);
                    i += 1;
                }
            }

            // Check for task item
            let (is_task, clean_text) = if item_text.starts_with("[ ] ") {
                (Some(false), item_text[4..].to_string())
            } else if item_text.starts_with("[x] ") || item_text.starts_with("[X] ") {
                (Some(true), item_text[4..].to_string())
            } else {
                (None, item_text)
            };

            let inner = self.parse_inline(&clean_text);
            items.push(ListItem { is_task, tokens: inner });
        }

        (Token::List(ordered, items), i)
    }

    fn parse_table(&self, lines: &[&str], start: usize) -> (Token, usize) {
        let header_line = lines[start].trim();
        let sep_line = lines[start + 1].trim();

        // Parse alignments
        let alignments: Vec<Alignment> = sep_line.trim_matches('|')
            .split('|')
            .map(|cell| {
                let c = cell.trim();
                match (c.starts_with(':'), c.ends_with(':')) {
                    (true, true) => Alignment::Center,
                    (false, true) => Alignment::Right,
                    (true, false) => Alignment::Left,
                    _ => Alignment::None,
                }
            })
            .collect();

        let header_cells: Vec<Vec<Token>> = parse_table_row(header_line)
            .iter()
            .map(|cell| self.parse_inline(cell))
            .collect();

        let mut rows = vec![header_cells];
        let mut i = start + 2;

        while i < lines.len() {
            let row_line = lines[i].trim();
            if row_line.is_empty() { break; }
            if !row_line.contains('|') && !row_line.starts_with('|') { break; }

            let row: Vec<Vec<Token>> = parse_table_row(row_line)
                .iter()
                .map(|cell| self.parse_inline(cell))
                .collect();
            rows.push(row);
            i += 1;
        }

        (Token::Table(rows, alignments), i)
    }

    pub fn parse_inline(&self, text: &str) -> Vec<Token> {
        let chars: Vec<char> = text.chars().collect();
        let mut tokens = Vec::new();
        let mut current = String::new();
        let mut i = 0;

        while i < chars.len() {
            let c = chars[i];

            // Hard break marker
            if c == '\x01' {
                if !current.is_empty() {
                    tokens.push(Token::Str(current.clone()));
                    current.clear();
                }
                tokens.push(Token::HardBreak);
                i += 1;
                continue;
            }

            // Soft break (newline)
            if c == '\n' {
                if !current.is_empty() {
                    tokens.push(Token::Str(current.clone()));
                    current.clear();
                }
                tokens.push(Token::SoftBreak);
                i += 1;
                continue;
            }

            // Escape
            if c == '\\' && i + 1 < chars.len() {
                let next = chars[i + 1];
                if "\\`*_{}[]()#+-.!~^".contains(next) {
                    current.push(next);
                    i += 2;
                    continue;
                }
            }

            // HTML entity or crowbook special: non-breaking space
            // (crowbook uses its own NBS handling)

            // Footnote reference [^label]
            if c == '[' && i + 1 < chars.len() && chars[i + 1] == '^' {
                if let Some(end) = find_close_bracket(&chars, i) {
                    let label: String = chars[i+2..end].iter().collect();
                    if !label.is_empty() && !label.contains(' ') {
                        if !current.is_empty() {
                            tokens.push(Token::Str(current.clone()));
                            current.clear();
                        }
                        tokens.push(Token::FootnoteRef(label));
                        i = end + 1;
                        continue;
                    }
                }
            }

            // Image ![alt](url "title")
            if c == '!' && i + 1 < chars.len() && chars[i + 1] == '[' {
                if let Some((img, new_i)) = try_parse_image(&chars, i) {
                    if !current.is_empty() {
                        tokens.push(Token::Str(current.clone()));
                        current.clear();
                    }
                    tokens.push(img);
                    i = new_i;
                    continue;
                }
            }

            // Link [text](url "title")
            if c == '[' {
                if let Some((link, new_i)) = self.try_parse_link(&chars, i) {
                    if !current.is_empty() {
                        tokens.push(Token::Str(current.clone()));
                        current.clear();
                    }
                    tokens.push(link);
                    i = new_i;
                    continue;
                }
            }

            // Inline code
            if c == '`' {
                let bt_count = count_char_run(&chars, i, '`');
                let end_marker: Vec<char> = std::iter::repeat('`').take(bt_count).collect();
                if let Some(code_end) = find_sequence(&chars, i + bt_count, &end_marker) {
                    let code: String = chars[i + bt_count..code_end].iter().collect();
                    if !current.is_empty() {
                        tokens.push(Token::Str(current.clone()));
                        current.clear();
                    }
                    // Normalize code: strip one leading/trailing space if present
                    let code = if code.starts_with(' ') && code.ends_with(' ') && code.len() > 2 {
                        code[1..code.len()-1].to_string()
                    } else {
                        code
                    };
                    tokens.push(Token::Code(code));
                    i = code_end + bt_count;
                    continue;
                }
            }

            // Strikethrough ~~text~~
            if c == '~' && i + 1 < chars.len() && chars[i + 1] == '~' {
                let search = vec!['~', '~'];
                if let Some(end) = find_sequence(&chars, i + 2, &search) {
                    let inner_text: String = chars[i+2..end].iter().collect();
                    if !current.is_empty() {
                        tokens.push(Token::Str(current.clone()));
                        current.clear();
                    }
                    let inner = self.parse_inline(&inner_text);
                    tokens.push(Token::Strikethrough(inner));
                    i = end + 2;
                    continue;
                }
            }

            // Superscript ^text^ (only when enabled)
            if self.superscript && c == '^' && i + 1 < chars.len() && chars[i + 1] != ' ' {
                let search = vec!['^'];
                if let Some(end) = find_sequence(&chars, i + 1, &search) {
                    let inner_text: String = chars[i+1..end].iter().collect();
                    if !inner_text.contains(' ') {
                        if !current.is_empty() {
                            tokens.push(Token::Str(current.clone()));
                            current.clear();
                        }
                        let inner = self.parse_inline(&inner_text);
                        tokens.push(Token::Superscript(inner));
                        i = end + 1;
                        continue;
                    }
                }
            }

            // Subscript ~text~ (only when superscript mode enabled)
            if self.superscript && c == '~' && i + 1 < chars.len() && chars[i + 1] != '~' && chars[i + 1] != ' ' {
                let search = vec!['~'];
                if let Some(end) = find_sequence(&chars, i + 1, &search) {
                    let inner_text: String = chars[i+1..end].iter().collect();
                    if !inner_text.contains(' ') && !inner_text.contains('~') {
                        if !current.is_empty() {
                            tokens.push(Token::Str(current.clone()));
                            current.clear();
                        }
                        let inner = self.parse_inline(&inner_text);
                        tokens.push(Token::Subscript(inner));
                        i = end + 1;
                        continue;
                    }
                }
            }

            // Strong/Em with * or _
            if (c == '*' || c == '_') {
                let run = count_char_run(&chars, i, c);
                if run >= 2 {
                    // Try strong (2+ delimiters)
                    let delim_str: String = std::iter::repeat(c).take(run).collect();
                    let search: Vec<char> = std::iter::repeat(c).take(run).collect();
                    if let Some(end) = find_sequence(&chars, i + run, &search) {
                        let inner_text: String = chars[i + run..end].iter().collect();
                        if !current.is_empty() {
                            tokens.push(Token::Str(current.clone()));
                            current.clear();
                        }
                        let inner = self.parse_inline(&inner_text);
                        tokens.push(Token::Strong(inner));
                        i = end + run;
                        continue;
                    }
                }
                if run >= 1 {
                    // Try em (1 delimiter)
                    let search = vec![c];
                    if let Some(end) = find_sequence(&chars, i + 1, &search) {
                        let inner_text: String = chars[i + 1..end].iter().collect();
                        if !inner_text.is_empty() {
                            if !current.is_empty() {
                                tokens.push(Token::Str(current.clone()));
                                current.clear();
                            }
                            let inner = self.parse_inline(&inner_text);
                            tokens.push(Token::Em(inner));
                            i = end + 1;
                            continue;
                        }
                    }
                }
            }

            current.push(c);
            i += 1;
        }

        if !current.is_empty() {
            tokens.push(Token::Str(current));
        }

        tokens
    }
}

fn extract_footnote_defs(text: &str) -> (String, Vec<(String, String)>) {
    let lines: Vec<&str> = text.lines().collect();
    let mut clean_lines = Vec::new();
    let mut fn_defs: Vec<(String, String)> = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        if trimmed.starts_with("[^") {
            if let Some(colon_pos) = trimmed.find("]:") {
                let label = &trimmed[2..colon_pos];
                if !label.contains(' ') {
                    let content = trimmed[colon_pos + 2..].trim().to_string();
                    let mut def_content = vec![content];
                    i += 1;
                    while i < lines.len() {
                        let nline = lines[i];
                        let ntrimmed = nline.trim();
                        if nline.starts_with("    ") || nline.starts_with('\t') {
                            def_content.push(ntrimmed.to_string());
                            i += 1;
                        } else if ntrimmed.is_empty() {
                            i += 1;
                        } else {
                            break;
                        }
                    }
                    fn_defs.push((label.to_string(), def_content.join(" ")));
                    continue;
                }
            }
        }

        clean_lines.push(line.to_string());
        i += 1;
    }

    (clean_lines.join("\n"), fn_defs)
}

fn atx_heading_level(line: &str) -> Option<usize> {
    if !line.starts_with('#') {
        return None;
    }
    let level = line.chars().take_while(|&c| c == '#').count();
    if level > 6 {
        return None;
    }
    let rest = &line[level..];
    if rest.is_empty() || rest.starts_with(' ') || rest.starts_with('\t') {
        Some(level)
    } else {
        None
    }
}

fn count_fence(line: &str, c: char) -> usize {
    line.chars().take_while(|&ch| ch == c).count()
}

fn is_horizontal_rule(line: &str) -> bool {
    let trimmed = line.trim();
    if trimmed.len() < 3 {
        return false;
    }
    let first = trimmed.chars().next().unwrap();
    if first != '-' && first != '*' && first != '_' {
        return false;
    }
    let non_space: String = trimmed.chars().filter(|&c| c != ' ' && c != '\t').collect();
    if non_space.len() < 3 {
        return false;
    }
    non_space.chars().all(|c| c == first)
}

fn is_list_marker(line: &str) -> bool {
    if line.is_empty() { return false; }
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return line.len() >= 2 && (line.as_bytes()[1] == b' ' || line.as_bytes()[1] == b'\t');
    }
    // Ordered
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    if !digits.is_empty() && digits.len() < 10 {
        let after = &line[digits.len()..];
        return after.starts_with(". ") || after.starts_with(".\t") || after == ".";
    }
    false
}

fn list_marker_len(line: &str) -> usize {
    let first = line.chars().next().unwrap();
    if first == '-' || first == '+' || first == '*' {
        return if line.len() > 2 { 2 } else { line.len() };
    }
    let digits: String = line.chars().take_while(|c| c.is_ascii_digit()).collect();
    let after = &line[digits.len()..];
    if after.starts_with(". ") {
        digits.len() + 2
    } else {
        digits.len() + 1
    }
}

fn is_table_separator(line: &str) -> bool {
    if !line.contains('-') {
        return false;
    }
    let cells: Vec<&str> = if line.starts_with('|') {
        line[1..].trim_end_matches('|').split('|').collect()
    } else {
        line.split('|').collect()
    };
    if cells.is_empty() { return false; }
    cells.iter().all(|cell| {
        let c = cell.trim();
        !c.is_empty() && c.chars().all(|ch| ch == '-' || ch == ':' || ch == ' ')
        && c.contains('-')
    })
}

fn parse_table_row(line: &str) -> Vec<String> {
    let line = line.trim();
    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').map(|s| s.trim().to_string()).collect()
}

fn is_block_html(line: &str) -> bool {
    if !line.starts_with('<') { return false; }
    let end = line[1..].find(|c: char| c == ' ' || c == '>' || c == '/').map(|p| p + 1).unwrap_or(line.len());
    let tag = &line[1..end.min(line.len())].to_lowercase();
    let block_tags = ["div", "p", "blockquote", "h1", "h2", "h3", "h4", "h5", "h6",
                       "ul", "ol", "li", "table", "tr", "td", "th", "thead", "tbody",
                       "article", "section", "nav", "aside", "header", "footer",
                       "pre", "figure", "figcaption", "details", "summary", "hr"];
    block_tags.contains(&tag.as_str())
}

fn find_close_bracket(chars: &[char], start: usize) -> Option<usize> {
    debug_assert_eq!(chars[start], '[');
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { return Some(i); }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

fn find_close_paren(chars: &[char], start: usize) -> Option<usize> {
    debug_assert_eq!(chars[start], '(');
    let mut depth = 0;
    let mut in_str = false;
    let mut str_char = '"';
    let mut i = start;
    while i < chars.len() {
        let c = chars[i];
        if in_str {
            if c == str_char { in_str = false; }
            else if c == '\\' { i += 1; }
        } else {
            match c {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 { return Some(i); }
                }
                '"' | '\'' => { in_str = true; str_char = c; }
                _ => {}
            }
        }
        i += 1;
    }
    None
}

fn try_parse_image(chars: &[char], start: usize) -> Option<(Token, usize)> {
    // start is at '!'
    debug_assert_eq!(chars[start], '!');
    if start + 1 >= chars.len() || chars[start + 1] != '[' { return None; }

    let bracket_end = find_close_bracket(chars, start + 1)?;
    if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' { return None; }

    let paren_end = find_close_paren(chars, bracket_end + 1)?;

    let alt: String = chars[start+2..bracket_end].iter().collect();
    let url_part: String = chars[bracket_end+2..paren_end].iter().collect();
    let (url, title) = parse_url_and_title(&url_part);

    Some((Token::Image(url, title, alt), paren_end + 1))
}

impl Parser {
    fn try_parse_link(&self, chars: &[char], start: usize) -> Option<(Token, usize)> {
        debug_assert_eq!(chars[start], '[');

        let bracket_end = find_close_bracket(chars, start)?;
        if bracket_end + 1 >= chars.len() || chars[bracket_end + 1] != '(' { return None; }

        let paren_end = find_close_paren(chars, bracket_end + 1)?;

        let text: String = chars[start+1..bracket_end].iter().collect();
        let url_part: String = chars[bracket_end+2..paren_end].iter().collect();
        let (url, title) = parse_url_and_title(&url_part);

        let inner = self.parse_inline(&text);
        Some((Token::Link(url, title, inner), paren_end + 1))
    }
}

fn parse_url_and_title(s: &str) -> (String, String) {
    let s = s.trim();
    // Try to find title in quotes after URL
    // URL can contain spaces if in <...>

    // Find title (last quoted string)
    if let Some(title_end) = s.rfind('"') {
        if let Some(title_start) = s[..title_end].rfind('"') {
            let url = s[..title_start].trim().to_string();
            let title = s[title_start+1..title_end].to_string();
            if !url.is_empty() {
                return (url, title);
            }
        }
    }
    if let Some(title_end) = s.rfind('\'') {
        if let Some(title_start) = s[..title_end].rfind('\'') {
            let url = s[..title_start].trim().to_string();
            let title = s[title_start+1..title_end].to_string();
            if !url.is_empty() {
                return (url, title);
            }
        }
    }

    (s.to_string(), String::new())
}

fn count_char_run(chars: &[char], start: usize, c: char) -> usize {
    chars[start..].iter().take_while(|&&ch| ch == c).count()
}

fn find_sequence(chars: &[char], start: usize, seq: &[char]) -> Option<usize> {
    if seq.is_empty() { return None; }
    'outer: for i in start..chars.len() {
        if i + seq.len() > chars.len() { break; }
        for (j, &sc) in seq.iter().enumerate() {
            if chars[i + j] != sc { continue 'outer; }
        }
        return Some(i);
    }
    None
}

/// Extract plain text from tokens for stats counting
pub fn extract_text(tokens: &[Token]) -> String {
    let mut text = String::new();
    for token in tokens {
        extract_token_text(token, &mut text);
    }
    text
}

fn extract_token_text(token: &Token, text: &mut String) {
    match token {
        Token::Str(s) => text.push_str(s),
        Token::Paragraph(inner) | Token::Header(_, inner) | Token::Em(inner) 
        | Token::Strong(inner) | Token::Strikethrough(inner) | Token::Superscript(inner)
        | Token::Subscript(inner) | Token::BlockQuote(inner) => {
            for t in inner { extract_token_text(t, text); }
        }
        Token::Link(_, _, inner) => {
            for t in inner { extract_token_text(t, text); }
        }
        Token::Code(s) => text.push_str(s),
        Token::CodeBlock(_, s) => text.push_str(s),
        Token::Image(_, _, alt) => text.push_str(alt),
        Token::SoftBreak | Token::HardBreak => text.push(' '),
        Token::List(_, items) => {
            for item in items {
                for t in &item.tokens { extract_token_text(t, text); }
            }
        }
        Token::Table(rows, _) => {
            for row in rows {
                for cell in row {
                    for t in cell { extract_token_text(t, text); }
                }
            }
        }
        Token::FootnoteDef(_, inner) => {
            for t in inner { extract_token_text(t, text); }
        }
        Token::Html(s) => text.push_str(s),
        _ => {}
    }
}
