fn load_or_default(custom_path: &Option<String>, default_name: &str) -> String {
    if let Some(path) = custom_path {
        load_file(path).unwrap_or_else(|_| templates::get_template(default_name).unwrap_or_default())
    } else {
        templates::get_template(default_name).unwrap_or_default()
    }
}

fn load_file(path: &str) -> Result<String, String> {
    fs::read_to_string(path).map_err(|e| e.to_string())
}

fn build_json_ld(book: &Book) -> String {
    let author = &book.options.author;
    let title = &book.options.title;
    let lang = &book.options.lang;

    let mut json = String::from("\n<script type = 'application/ld+json'>\n{\n");
    json.push_str("    \"@context\": \"http://schema.org/\",\n");
    json.push_str("    \"@type\": \"Book\",\n");
    json.push_str(&format!("    \"author\": \"{}\",\n", json_escape(author)));
    json.push_str(&format!("    \"name\": \"{}\",\n", json_escape(title)));

    if let Some(ref desc) = book.options.description {
        json.push_str(&format!("    \"description\": \"{}\",\n", json_escape(desc)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref subj) = book.options.subject {
        json.push_str(&format!("    \"genre\": \"{}\",\n", json_escape(subj)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref ver) = book.options.version {
        json.push_str(&format!("    \"version\": \"{}\",\n", json_escape(ver)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref lic) = book.options.license {
        json.push_str(&format!("    \"license\": \"{}\",\n", json_escape(lic)));
    } else {
        json.push_str("    \n");
    }

    json.push_str(&format!("    \"inLanguage\": \"{}\"\n", lang));
    json.push_str("}\n</script>\n");
    json
}

fn json_escape(s: &str) -> String {
    s.replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r")
}

pub fn html_escape_str(s: &str) -> String {
    s.replace('&', "&amp;")
     .replace('<', "&lt;")
     .replace('>', "&gt;")
     .replace('"', "&quot;")
}

fn html_escape(s: &str) -> String {
    html_escape_str(s)
}

pub fn render_liquid_template(template: &str, lang: &str, vars: &HashMap<String, String>) -> String {
    let mut result = template.to_string();

    // Process {% if lang | eq: "xx" %} blocks
    while let Some(start) = result.find("{% if lang | eq:") {
        if let Some(cond_end) = result[start..].find("%}") {
            let cond = &result[start + 3..start + cond_end].trim().to_string();
            // Extract language from condition
            let lang_val = cond.trim_start_matches("if lang | eq:").trim().trim_matches('"');

            let endif = "{% endif %}";
            let block_start = start + cond_end + 2;

            if let Some(end_pos) = result[block_start..].find(endif) {
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if lang == lang_val {
                    inner
                } else {
                    String::new()
                };

                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif.len()..]);
            } else {
                break;
            }
        } else {
            break;
        }
    }

    // Replace variables
    for (key, val) in vars {
        result = result.replace(&format!("{{{{{}}}}}", key), val);
    }

    result
}

fn render_liquid_template_with_flags(template: &str, lang: &str, vars: &HashMap<String, String>, flags: &[(&str, bool)]) -> String {
    let mut result = template.to_string();

    // Process if/endif blocks for flags
    for (flag, value) in flags {
        let if_tag = format!("{{% if {} %}}", flag);
        let endif_tag = "{% endif %}";

        while let Some(start) = result.find(&if_tag) {
            if let Some(end_pos) = result[start + if_tag.len()..].find(endif_tag) {
                let block_start = start + if_tag.len();
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if *value { inner } else { String::new() };
                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
            } else {
                break;
            }
        }
    }

    // Also handle {% if not flag %} ... {% endif %}
    for (flag, value) in flags {
        let if_tag = format!("{{% if not {} %}}", flag);
        let endif_tag = "{% endif %}";

        while let Some(start) = result.find(&if_tag) {
            if let Some(end_pos) = result[start + if_tag.len()..].find(endif_tag) {
                let block_start = start + if_tag.len();
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if !value { inner } else { String::new() };
                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
            } else {
                break;
            }
        }
    }

    result = render_liquid_template(&result, lang, vars);
    result
}

fn render_standalone_template(template: &str, vars: &HashMap<String, String>, 
    has_toc: bool, has_subtitle: bool, has_autograph: bool, 
    one_chapter: bool, highlight_code: bool, is_rtl: bool) -> String {
    let mut result = template.to_string();

    let flags = [
