    result = result.replace("{{title}}", title);
    result = result.replace("{{link}}", &link.to_string());

    result
}

fn process_liquid_if(template: &str, condition: &str, value: bool) -> String {
    let if_tag = format!("{{% if {} %}}", condition);
    let endif_tag = "{% endif %}";

    let mut result = template.to_string();

    while let Some(start) = result.find(&if_tag) {
        if let Some(end) = result[start..].find(endif_tag) {
            let end_abs = start + end + endif_tag.len();
            let inner_start = start + if_tag.len();
            let inner_end = start + end;

            if value {
                // Keep content
                let inner = result[inner_start..inner_end].to_string();
                result = format!("{}{}{}", &result[..start], inner, &result[end_abs..]);
            } else {
                // Remove content
                result = format!("{}{}", &result[..start], &result[end_abs..]);
            }
        } else {
            break;
        }
    }

    result
}

pub fn render_html(book: &Book) -> Result<String, String> {
    let lang = &book.options.lang;

    // Get templates
    let css_template = load_or_default(&book.options.html_css, "html.css");
    let css_colors_template = book.options.html_css_colors.as_ref()
        .and_then(|p| load_file(p).ok());
    let js_template = load_or_default(&book.options.html_js, "html.js");
    let print_css_template = load_or_default(&book.options.html_css_print, "html.css.print");
    let standalone_template = load_or_default(&book.options.html_standalone_template, "html.standalone.template");
    let standalone_js_template = load_or_default(&book.options.html_standalone_js, "html.standalone.js");

    // Render CSS
    let mut css = render_liquid_template(&css_template, lang, &HashMap::new());
    if let Some(extra_css) = &book.options.html_css_add {
        css.push_str(extra_css);
    }

    // Get SVG data
    let menu_svg = templates::menu_svg_b64();
    let book_svg = templates::book_svg_b64();
    let pages_svg = templates::pages_svg_b64();

    let menu_svg_uri = format!("data:image/svg+xml;base64,{}", menu_svg);
    let book_svg_uri = format!("data:image/svg+xml;base64,{}", book_svg);
    let pages_svg_uri = format!("data:image/svg+xml;base64,{}", pages_svg);

    // Render all chapters
    let mut renderer = HtmlRenderer::new(book);
    let mut chapters_html = String::new();
    let mut toc_items: Vec<(u32, String, String)> = Vec::new();  // (level, id, text)
    let mut link_counter_after = 0u32;

    // Build TOC from all chapters
    let mut link_num: u32 = 0;

    // First pass: collect TOC info
    let mut toc_links: Vec<(String, String)> = Vec::new(); // (link_id, display_text)

    {
        let mut lc = 0u32;
        for (ci, chapter) in book.chapters.iter().enumerate() {
            for token in &chapter.tokens {
                if let Token::Header(level, inner) = token {
                    if *level == 1 {
                        lc += 1;
                        let title = extract_plain_text(inner);
                        let num = chapter.number.unwrap_or(0);
                        let display = if chapter.is_part {
                            title.clone()
                        } else if book.options.rendering_num_depth >= 1 && num > 0 {
                            format!("{}. {}", num, title)
                        } else {
                            title.clone()
                        };
                        toc_links.push((format!("link-{}", lc), display));
                    }
                }
            }
        }
    }

    // Render chapters
    renderer.link_counter = 0;
    renderer.para_counter = 0;
    renderer.footnote_counter = 0;

    let mut chapter_divs = Vec::new();

    for (ci, chapter) in book.chapters.iter().enumerate() {
        renderer.chapter_idx = ci;
        renderer.footnote_counter = 0;

        let (chapter_content, _warns) = renderer.render_chapter_html(chapter, ci);

        let chapter_class = if book.options.html_standalone_one_chapter {
            "chapter".to_string()
        } else {
            "chapter".to_string()
        };

        let chapter_div = format!("<div id = \"chapter-{}\" class = \"{}\">\n  {}\n</div>",
            ci, chapter_class, chapter_content);
        chapter_divs.push(chapter_div);
    }

    let content = chapter_divs.join("");

    // Build TOC HTML
    let toc_html = if !toc_links.is_empty() {
        let mut toc = String::from("<ul>\n");
        for (link_id, text) in &toc_links {
            toc.push_str(&format!("      <li><a href=\"#{}\">{}</a></li>\n", link_id, html_escape_str(text)));
        }
        toc.push_str("    </ul>\n");
        toc
    } else {
        String::new()
    };

    let has_toc = !toc_links.is_empty();

    // Build JSON-LD data
    let json_data = build_json_ld(book);

    // Build favicon HTML
    let favicon = if let Some(ref icon_path) = book.options.html_icon {
        format!("<link rel=\"icon\" href=\"{}\" />", icon_path)
    } else {
        String::new()
    };

    // Render the script
    let mut js_vars: HashMap<String, String> = HashMap::new();
    js_vars.insert("menu_svg".to_string(), menu_svg_uri.clone());
    js_vars.insert("book_svg".to_string(), book_svg_uri.clone());
    js_vars.insert("pages_svg".to_string(), pages_svg_uri.clone());
    js_vars.insert("loc_display_all".to_string(), get_str(lang, "display_all").to_string());
    js_vars.insert("loc_display_one".to_string(), get_str(lang, "display_one").to_string());

    let common_script = render_liquid_template(&js_template, lang, &js_vars);
    js_vars.insert("common_script".to_string(), common_script);

    let one_chapter = book.options.html_standalone_one_chapter;
    let script_content = render_liquid_template_with_flags(&standalone_js_template, lang, &js_vars, 
        &[("one_chapter", one_chapter)]);

    // Build the full HTML
    let mut template_vars: HashMap<String, String> = HashMap::new();
    template_vars.insert("lang".to_string(), lang.clone());
    template_vars.insert("author_raw".to_string(), book.options.author.clone());
    template_vars.insert("author".to_string(), html_escape_str(&book.options.author));
    template_vars.insert("title_raw".to_string(), book.options.title.clone());
    template_vars.insert("title".to_string(), html_escape_str(&book.options.title));
    template_vars.insert("subtitle".to_string(), html_escape_str(book.options.subtitle.as_deref().unwrap_or("")));
    template_vars.insert("autograph".to_string(), html_escape_str(book.options.autograph.as_deref().unwrap_or("")));
    template_vars.insert("style".to_string(), css);
    template_vars.insert("print_style".to_string(), render_liquid_template(&print_css_template, lang, &HashMap::new()));
    template_vars.insert("script".to_string(), script_content);
    template_vars.insert("content".to_string(), content);
    template_vars.insert("toc".to_string(), toc_html);
    template_vars.insert("json_data".to_string(), json_data);
    template_vars.insert("favicon".to_string(), favicon);
    template_vars.insert("header".to_string(), book.options.html_header.as_deref().unwrap_or("").to_string());
    template_vars.insert("footer".to_string(), book.options.html_footer.as_deref().unwrap_or("").to_string());
    template_vars.insert("menu_svg".to_string(), menu_svg_uri);
    template_vars.insert("book_svg".to_string(), book_svg_uri);
    template_vars.insert("loc_toc".to_string(), get_str(lang, "toc").to_string());
    template_vars.insert("loc_display_all".to_string(), get_str(lang, "display_all").to_string());

    let has_subtitle = book.options.subtitle.is_some();
    let has_autograph = book.options.autograph.is_some();

    let html = render_standalone_template(&standalone_template, &template_vars, has_toc, has_subtitle, has_autograph, one_chapter, false, false);

    Ok(html)
}

pub fn render_html_dir(book: &Book, output: Option<&str>) -> Result<(), String> {
    let out_dir = match output {
        Some(p) => std::path::PathBuf::from(p),
        None => return Err("No output directory specified".to_string()),
    };

    // Check if directory exists and is not a file
    if out_dir.exists() && !out_dir.is_dir() {
        return Err(format!("{} already exists and is not a directory", out_dir.display()));
    }

    fs::create_dir_all(&out_dir)
        .map_err(|e| format!("Could not create directory: {}", e))?;

    let lang = &book.options.lang;

    // Write CSS files
    let css_content = load_or_default(&book.options.html_css, "html.css");
    let css = render_liquid_template(&css_content, lang, &HashMap::new());
    fs::write(out_dir.join("stylesheet.css"), css.as_bytes())
        .map_err(|e| format!("Could not write stylesheet: {}", e))?;

    let print_css_content = load_or_default(&book.options.html_css_print, "html.css.print");
    let print_css = render_liquid_template(&print_css_content, lang, &HashMap::new());
    fs::write(out_dir.join("print.css"), print_css.as_bytes())
        .map_err(|e| format!("Could not write print.css: {}", e))?;

    // Write JS
    let js_content = load_or_default(&book.options.html_js, "html.js");
    let js = render_liquid_template(&js_content, lang, &HashMap::new());

    // Write menu.svg
    fs::write(out_dir.join("menu.svg"), templates::menu_svg_b64().as_bytes())
        .ok();

    // Render chapters
    let dir_template = load_or_default(&book.options.html_dir_template, "html.dir.template");
    let mut renderer = HtmlRenderer::new(book);

    // Build TOC
    let mut toc_links: Vec<(String, String, String)> = Vec::new();
    {
        let mut lc = 0u32;
        for (ci, chapter) in book.chapters.iter().enumerate() {
            let fname = format!("chapter_{:03}.html", ci);
            for token in &chapter.tokens {
                if let Token::Header(1, inner) = token {
                    lc += 1;
                    let title = extract_plain_text(inner);
                    let num = chapter.number.unwrap_or(0);
                    let display = if chapter.is_part {
                        title.clone()
                    } else if book.options.rendering_num_depth >= 1 && num > 0 {
                        format!("{}. {}", num, title)
                    } else {
                        title.clone()
                    };
                    toc_links.push((fname.clone(), format!("link-{}", lc), display));
                    break;
                }
            }
        }
    }

    let toc_html = {
        let mut t = String::from("<ul>\n");
        for (fname, _, text) in &toc_links {
            t.push_str(&format!("    <li><a href=\"{}\">{}</a></li>\n", fname, html_escape_str(text)));
        }
        t.push_str("  </ul>");
        t
    };

    for (ci, chapter) in book.chapters.iter().enumerate() {
        renderer.chapter_idx = ci;
        renderer.footnote_counter = 0;

        let (chapter_content, _) = renderer.render_chapter_html(chapter, ci);
        let fname = format!("chapter_{:03}.html", ci);

        let prev_link = if ci > 0 {
            let prev_fname = format!("chapter_{:03}.html", ci - 1);
            format!("<p class=\"prev_chapter\"><a href=\"{}\">&lt; Prev</a></p>", prev_fname)
        } else {
            String::new()
        };

        let next_link = if ci + 1 < book.chapters.len() {
            let next_fname = format!("chapter_{:03}.html", ci + 1);
            format!("<p class=\"next_chapter\"><a href=\"{}\">Next &gt;</a></p>", next_fname)
        } else {
            String::new()
        };

        let chapter_title = extract_plain_text_from_tokens(&chapter.tokens);
        let num = chapter.number.unwrap_or(0);
        let chapter_title_for_display = if book.options.rendering_num_depth >= 1 && num > 0 && !chapter.is_part {
            format!("{}. {}", num, chapter_title)
        } else {
            chapter_title.clone()
        };

        let json_data = build_json_ld(book);
        let favicon = if let Some(ref p) = book.options.html_icon {
            format!("<link rel=\"icon\" href=\"{}\" />", p)
        } else {
            String::new()
        };

        let mut vars: HashMap<String, String> = HashMap::new();
        vars.insert("lang".to_string(), lang.clone());
        vars.insert("author_raw".to_string(), book.options.author.clone());
        vars.insert("title_raw".to_string(), book.options.title.clone());
        vars.insert("title".to_string(), html_escape_str(&book.options.title));
        vars.insert("chapter_title_raw".to_string(), chapter_title_for_display.clone());
        vars.insert("content".to_string(), chapter_content);
        vars.insert("toc".to_string(), toc_html.clone());
        vars.insert("json_data".to_string(), json_data);
        vars.insert("favicon".to_string(), favicon);
        vars.insert("header".to_string(), book.options.html_header.as_deref().unwrap_or("").to_string());
        vars.insert("footer".to_string(), book.options.html_footer.as_deref().unwrap_or("").to_string());
        vars.insert("loc_toc".to_string(), get_str(lang, "toc").to_string());
        vars.insert("script".to_string(), js.clone());
        vars.insert("prev_chapter".to_string(), prev_link);
        vars.insert("next_chapter".to_string(), next_link);

        let chapter_html = render_dir_template(&dir_template, &vars, true, false);

        fs::write(out_dir.join(&fname), chapter_html.as_bytes())
            .map_err(|e| format!("Could not write chapter HTML: {}", e))?;
    }

    // Write index.html
    let mut index_vars: HashMap<String, String> = HashMap::new();
    index_vars.insert("lang".to_string(), lang.clone());
    index_vars.insert("author_raw".to_string(), book.options.author.clone());
    index_vars.insert("title_raw".to_string(), book.options.title.clone());
    index_vars.insert("title".to_string(), html_escape_str(&book.options.title));
    index_vars.insert("chapter_title_raw".to_string(), String::new());
    index_vars.insert("content".to_string(), String::new());
    index_vars.insert("toc".to_string(), toc_html);
    index_vars.insert("json_data".to_string(), build_json_ld(book));
    index_vars.insert("favicon".to_string(), String::new());
    index_vars.insert("header".to_string(), String::new());
    index_vars.insert("footer".to_string(), String::new());
    index_vars.insert("loc_toc".to_string(), get_str(lang, "toc").to_string());
    index_vars.insert("script".to_string(), js);
    index_vars.insert("prev_chapter".to_string(), String::new());
    index_vars.insert("next_chapter".to_string(), String::new());

    let index_html = render_dir_template(&dir_template, &index_vars, false, false);
    fs::write(out_dir.join("index.html"), index_html.as_bytes())
        .map_err(|e| format!("Could not write index HTML: {}", e))?;

    Ok(())
}

fn extract_plain_text_from_tokens(tokens: &[Token]) -> String {
    for token in tokens {
        if let Token::Header(1, inner) = token {
            return extract_plain_text(inner);
        }
    }
    String::new()
}

fn load_or_default(custom_path: &Option<String>, default_name: &str) -> String {
    if let Some(path) = custom_path {
        load_file(path).unwrap_or_else(|_| templates::get_template(default_name).unwrap_or_default())
    } else {
        templates::get_template(default_name).unwrap_or_default()
    }
}

fn load_file(path: &str) -> Result<String, String> {
    fs::read_to_string(path).map_err(|e| e.to_string())
}

fn build_json_ld(book: &Book) -> String {
    let author = &book.options.author;
    let title = &book.options.title;
    let lang = &book.options.lang;

    let mut json = String::from("\n<script type = 'application/ld+json'>\n{\n");
    json.push_str("    \"@context\": \"http://schema.org/\",\n");
    json.push_str("    \"@type\": \"Book\",\n");
    json.push_str(&format!("    \"author\": \"{}\",\n", json_escape(author)));
    json.push_str(&format!("    \"name\": \"{}\",\n", json_escape(title)));

    if let Some(ref desc) = book.options.description {
        json.push_str(&format!("    \"description\": \"{}\",\n", json_escape(desc)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref subj) = book.options.subject {
        json.push_str(&format!("    \"genre\": \"{}\",\n", json_escape(subj)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref ver) = book.options.version {
        json.push_str(&format!("    \"version\": \"{}\",\n", json_escape(ver)));
    } else {
        json.push_str("    \n");
    }

    if let Some(ref lic) = book.options.license {
        json.push_str(&format!("    \"license\": \"{}\",\n", json_escape(lic)));
    } else {
        json.push_str("    \n");
    }

    json.push_str(&format!("    \"inLanguage\": \"{}\"\n", lang));
    json.push_str("}\n</script>\n");
    json
}

fn json_escape(s: &str) -> String {
    s.replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r")
}

pub fn html_escape_str(s: &str) -> String {
    s.replace('&', "&amp;")
     .replace('<', "&lt;")
     .replace('>', "&gt;")
     .replace('"', "&quot;")
}

fn html_escape(s: &str) -> String {
    html_escape_str(s)
}

pub fn render_liquid_template(template: &str, lang: &str, vars: &HashMap<String, String>) -> String {
    let mut result = template.to_string();

    // Process {% if lang | eq: "xx" %} blocks
    while let Some(start) = result.find("{% if lang | eq:") {
        if let Some(cond_end) = result[start..].find("%}") {
            let cond = &result[start + 3..start + cond_end].trim().to_string();
            // Extract language from condition
            let lang_val = cond.trim_start_matches("if lang | eq:").trim().trim_matches('"');

            let endif = "{% endif %}";
            let block_start = start + cond_end + 2;

            if let Some(end_pos) = result[block_start..].find(endif) {
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if lang == lang_val {
                    inner
                } else {
                    String::new()
                };

                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif.len()..]);
            } else {
                break;
            }
        } else {
            break;
        }
    }

    // Replace variables
    for (key, val) in vars {
        result = result.replace(&format!("{{{{{}}}}}", key), val);
    }

    result
}

fn render_liquid_template_with_flags(template: &str, lang: &str, vars: &HashMap<String, String>, flags: &[(&str, bool)]) -> String {
    let mut result = template.to_string();

    // Process if/endif blocks for flags
    for (flag, value) in flags {
        let if_tag = format!("{{% if {} %}}", flag);
        let endif_tag = "{% endif %}";

        while let Some(start) = result.find(&if_tag) {
            if let Some(end_pos) = result[start + if_tag.len()..].find(endif_tag) {
                let block_start = start + if_tag.len();
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if *value { inner } else { String::new() };
                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
            } else {
                break;
            }
        }
    }

    // Also handle {% if not flag %} ... {% endif %}
    for (flag, value) in flags {
        let if_tag = format!("{{% if not {} %}}", flag);
        let endif_tag = "{% endif %}";

        while let Some(start) = result.find(&if_tag) {
            if let Some(end_pos) = result[start + if_tag.len()..].find(endif_tag) {
                let block_start = start + if_tag.len();
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if !value { inner } else { String::new() };
                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
            } else {
                break;
            }
        }
    }

    result = render_liquid_template(&result, lang, vars);
    result
}

fn render_standalone_template(template: &str, vars: &HashMap<String, String>, 
    has_toc: bool, has_subtitle: bool, has_autograph: bool, 
    one_chapter: bool, highlight_code: bool, is_rtl: bool) -> String {
    let mut result = template.to_string();

    let flags = [
        ("has_toc", has_toc),
        ("has_subtitle", has_subtitle),
        ("has_autograph", has_autograph),
        ("one_chapter", one_chapter),
        ("highlight_code", highlight_code),
    ];

    for (flag, value) in &flags {
        let if_tag = format!("{{% if {} %}}", flag);
        let endif_tag = "{% endif %}";

        while let Some(start) = result.find(&if_tag) {
            if let Some(end_pos) = result[start + if_tag.len()..].find(endif_tag) {
                let block_start = start + if_tag.len();
                let block_end = block_start + end_pos;
                let inner = result[block_start..block_end].to_string();

                let replacement = if *value { inner } else { String::new() };
                result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
            } else {
                break;
            }
        }
    }

    for (key, val) in vars {
        result = result.replace(&format!("{{{{{}}}}}", key), val);
    }

    result
}

fn render_dir_template(template: &str, vars: &HashMap<String, String>, is_chapter: bool, highlight_code: bool) -> String {
    let flags = [
