            format!("{}.epub", sanitize_filename(&book.options.title))
        }
    };

    let full_path = if Path::new(&out_path).is_absolute() {
        std::path::PathBuf::from(&out_path)
    } else {
        book.base_dir.join(&out_path)
    };

    // Write the EPUB (zip) file
    write_epub(&full_path.to_string_lossy(), &epub_data)?;

    Ok(warnings)
}

fn count_h1(tokens: &[Token]) -> usize {
    let mut count = 0;
    for token in tokens {
        if let Token::Header(1, _) = token {
            count += 1;
        }
    }
    count
}

fn check_zip_command(cmd: &str) -> bool {
    std::process::Command::new(cmd)
        .arg("--version")
        .output()
        .is_ok()
}

fn sanitize_filename(s: &str) -> String {
    s.chars()
        .map(|c| if c.is_alphanumeric() || c == '-' || c == '_' { c } else { '_' })
        .collect()
}

struct EpubFiles {
    files: Vec<(String, Vec<u8>)>,
}

impl EpubFiles {
    fn new() -> Self {
        EpubFiles { files: Vec::new() }
    }

    fn add(&mut self, name: String, content: Vec<u8>) {
        self.files.push((name, content));
    }

    fn add_str(&mut self, name: String, content: String) {
        self.add(name, content.into_bytes());
    }
}

fn generate_epub(book: &Book, warnings: &mut Vec<String>) -> Result<EpubFiles, String> {
    let mut files = EpubFiles::new();
    let lang = &book.options.lang;

    // mimetype - must be first and uncompressed
    files.add_str("mimetype".to_string(), "application/epub+zip".to_string());

    // META-INF/container.xml
    files.add_str("META-INF/container.xml".to_string(), 
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<container version=\"1.0\" xmlns=\"urn:oasis:names:tc:opendocument:xmlns:container\">\n  <rootfiles>\n    <rootfile full-path=\"OEBPS/content.opf\" media-type=\"application/oebps-package+xml\" />\n  </rootfiles>\n</container>\n".to_string());

    // Apple iBooks
    files.add_str("META-INF/com.apple.ibooks.display-options.xml".to_string(),
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<display_options>\n  <platform name=\"*\">\n    <option name=\"specified-fonts\">true</option>\n  </platform>\n</display_options>\n".to_string());

    // Generate CSS
    let css_template = if let Some(ref css_path) = book.options.epub_css {
        fs::read_to_string(css_path).unwrap_or_else(|_| templates::get_template("epub.css").unwrap_or_default())
    } else {
        templates::get_template("epub.css").unwrap_or_default()
    };

    let mut css = css_template;
    if book.options.rendering_initials {
        css.push_str("\n\nspan.initial { \n    float: left;\n    font-size: 285%;\n    font-weight: bold;\n    margin-right: 0.05em;\n    line-height: 0.8em;\n}\n\np.first-para {\n    text-indent: 0;\n}\n");
    }
    // Add nbsp CSS
    css.push_str("\n/* Use this for escape narrow space so it is non-breaking */\n.nnbsp {\n    /* white-space: nowrap;*/\n    word-spacing: -0.13em;\n    /* Following necessary for Kobo EPUB3 reader??? */\n    margin: 0;\n    padding: 0;\n}\n");

    if let Some(ref extra_css) = book.options.epub_css_add {
        css.push_str(extra_css);
    }

    files.add_str("OEBPS/stylesheet.css".to_string(), css);

    // Generate title page
    let titlepage_template = if let Some(ref path) = book.options.epub_titlepage_xhtml {
        fs::read_to_string(path).unwrap_or_else(|_| templates::get_template("epub.titlepage.xhtml").unwrap_or_default())
    } else {
        templates::get_template("epub.titlepage.xhtml").unwrap_or_default()
    };

    let title_page = render_epub_titlepage(&titlepage_template, book);
    files.add_str("OEBPS/title_page.xhtml".to_string(), title_page);

    // Generate chapters
    let chapter_template = if let Some(ref path) = book.options.epub_chapter_xhtml {
        fs::read_to_string(path).unwrap_or_else(|_| templates::get_template("epub.chapter.xhtml").unwrap_or_default())
    } else {
        templates::get_template("epub.chapter.xhtml").unwrap_or_default()
    };

    let mut chapter_files = Vec::new();

    let mut renderer = EpubRenderer::new(book);

    for (ci, chapter) in book.chapters.iter().enumerate() {
        renderer.chapter_idx = ci;
        renderer.footnote_counter = 0;
        renderer.link_counter_start = renderer.link_counter;

        let chapter_content = renderer.render_chapter(chapter);

        let num = chapter.number.unwrap_or(0);
        let chapter_title = extract_plain_text_h1(&chapter.tokens);
        let chapter_title_display = if book.options.rendering_num_depth >= 1 && num > 0 && !chapter.is_part {
            format!("{}. {}", num, chapter_title)
        } else {
            chapter_title.clone()
        };

        let chapter_filename = format!("chapter_{:03}.xhtml", ci);

        let chapter_html = render_epub_chapter(
            &chapter_template, 
            &chapter_content, 
            &chapter_title_display,
            lang
        );

        files.add_str(format!("OEBPS/{}", chapter_filename), chapter_html);
        chapter_files.push((chapter_filename, chapter_title_display));
    }

    // Check for conflicts
    let first_chapters: Vec<_> = chapter_files.iter().enumerate()
        .filter(|(_, (_, title))| !title.is_empty())
        .collect();

    // Generate content.opf
    let uuid = generate_uuid();
    let opf = generate_opf(book, &uuid, &chapter_files, warnings);
    files.add_str("OEBPS/content.opf".to_string(), opf);

    // Generate toc.ncx
    let ncx = generate_ncx(book, &uuid, &chapter_files);
    files.add_str("OEBPS/toc.ncx".to_string(), ncx);

    // Generate nav.xhtml
    let nav = generate_nav(book, &chapter_files);
    files.add_str("OEBPS/nav.xhtml".to_string(), nav);

    Ok(files)
}

fn render_epub_titlepage(template: &str, book: &Book) -> String {
    let lang = &book.options.lang;
    let has_subtitle = book.options.subtitle.is_some();
    let has_autograph = book.options.autograph.is_some();

    let mut result = template.to_string();

    // Process if blocks
    let flags = [("has_subtitle", has_subtitle), ("has_autograph", has_autograph)];
    for (flag, value) in &flags {
        let if_tag = format!("{{% if {}%}}", flag);
        let if_tag2 = format!("{{% if {} %}}", flag);
        let endif_tag = "{% endif %}";

        for tag in &[if_tag, if_tag2] {
            while let Some(start) = result.find(tag.as_str()) {
                if let Some(end_pos) = result[start + tag.len()..].find(endif_tag) {
                    let block_start = start + tag.len();
                    let block_end = block_start + end_pos;
                    let inner = result[block_start..block_end].to_string();
                    let replacement = if *value { inner } else { String::new() };
                    result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
                } else {
                    break;
                }
            }
        }
    }

    result = result.replace("{{lang}}", lang);
    result = result.replace("{{author}}", &html_escape_str(&book.options.author));
    result = result.replace("{{title_raw}}", &book.options.title);
    result = result.replace("{{title}}", &html_escape_str(&book.options.title));
    result = result.replace("{{subtitle}}", &html_escape_str(book.options.subtitle.as_deref().unwrap_or("")));
    result = result.replace("{{autograph}}", &html_escape_str(book.options.autograph.as_deref().unwrap_or("")));

    result
}

fn render_epub_chapter(template: &str, content: &str, title: &str, lang: &str) -> String {
    let mut result = template.to_string();
    result = result.replace("{{lang}}", lang);
    result = result.replace("{{chapter_title_raw}}", &html_escape_str(title));
    result = result.replace("{{content}}", content);
    result
}

fn generate_opf(book: &Book, uuid: &str, chapters: &[(String, String)], warnings: &mut Vec<String>) -> String {
    let lang = &book.options.lang;
    let version = book.options.epub_version;

    let version_str = if version >= 3 { "3.0" } else { "2.0" };

    let mut opf = format!("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<package version=\"{}\" xmlns=\"http://www.idpf.org/2007/opf\" unique-identifier=\"epub-id-1\">\n", version_str);

    opf.push_str("  <metadata xmlns:dc=\"http://purl.org/dc/elements/1.1/\"\n            xmlns:opf=\"http://www.idpf.org/2007/opf\">\n");
    opf.push_str(&format!("    <dc:identifier id=\"epub-id-1\">urn:uuid:{}</dc:identifier>\n", uuid));
    opf.push_str(&format!("    <dc:title>{}</dc:title>\n", html_escape_str(&book.options.title)));

    if let Some(ref subtitle) = book.options.subtitle {
        opf.push_str(&format!("    <dc:description>{}</dc:description>\n", html_escape_str(subtitle)));
    } else {
        opf.push_str("    \n");
    }

    if let Some(ref desc) = book.options.description {
        opf.push_str(&format!("    <dc:description>{}</dc:description>\n", html_escape_str(desc)));
    } else {
        opf.push_str("    \n");
    }

    if version >= 3 {
        opf.push_str(&format!("    <dc:language id=\"epub-creator-0\">{}</dc:language>\n", lang));
    } else {
        opf.push_str(&format!("    <dc:language>{}</dc:language>\n", lang));
    }

    if let Some(ref subj) = book.options.subject {
        opf.push_str(&format!("    <dc:subject>{}</dc:subject>\n", html_escape_str(subj)));
    } else {
        opf.push_str("    \n");
    }

    if let Some(ref date) = book.options.date {
        opf.push_str(&format!("    <dc:date>{}</dc:date>\n", html_escape_str(date)));
    } else {
        opf.push_str("    \n");
    }

    if version >= 3 {
        // Add dcterms:modified timestamp
        let now = get_timestamp();
        opf.push_str(&format!("    <meta property=\"dcterms:modified\">{}</meta>\n", now));
        opf.push_str("\n");
    }

    if !book.options.author.is_empty() {
        if version >= 3 {
            opf.push_str(&format!("    <dc:creator id=\"epub-creator-1\">{}</dc:creator>\n", html_escape_str(&book.options.author)));
            opf.push_str("    <meta refines=\"#epub-creator-1\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n");
        } else {
            opf.push_str(&format!("    <dc:creator opf:role=\"aut\">{}</dc:creator>\n", html_escape_str(&book.options.author)));
        }
        opf.push_str("    \n");
    } else {
        opf.push_str("    \n");
    }

    opf.push_str("\n  </metadata>\n");

    // Manifest
    opf.push_str("  <manifest>\n");
    opf.push_str("    <item id=\"ncx\" href=\"toc.ncx\" media-type=\"application/x-dtbncx+xml\"/>\n");

    if version >= 3 {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\" properties=\"nav\"/>\n");
    } else {
        opf.push_str("    <item id=\"nav\" href=\"nav.xhtml\" media-type=\"application/xhtml+xml\"/>\n");
    }

    opf.push_str("    <item media-type=\"application/xhtml+xml\" id=\"id_title_page.xhtml\" href=\"title_page.xhtml\"/>\n");

    for (filename, _) in chapters {
        let id = format!("id_{}", filename);
        opf.push_str(&format!("    <item media-type=\"application/xhtml+xml\" id=\"{}\" href=\"{}\"/>\n", id, filename));
    }

    if let Some(ref cover) = book.options.cover {
        let cover_path = std::path::Path::new(cover);
        let ext = cover_path.extension().and_then(|e| e.to_str()).unwrap_or("");
        let mime = match ext.to_lowercase().as_str() {
            "jpg" | "jpeg" => "image/jpeg",
            "png" => "image/png",
            "gif" => "image/gif",
            "svg" => "image/svg+xml",
            _ => "image/jpeg",
        };
        let fname = cover_path.file_name().and_then(|n| n.to_str()).unwrap_or("cover.jpg");
        opf.push_str(&format!("    <item id=\"cover-image\" href=\"{}\" media-type=\"{}\" properties=\"cover-image\"/>\n", fname, mime));
    }

    opf.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
    opf.push_str("  </manifest>\n");

    // Spine
    let dir_attr = if version >= 3 { " page-progression-direction=\"ltr\"" } else { "" };
    opf.push_str(&format!("  <spine toc=\"ncx\"{}>\n", dir_attr));
    opf.push_str("    <itemref idref=\"id_title_page.xhtml\"/>\n");
    for (filename, _) in chapters {
        let id = format!("id_{}", filename);
        opf.push_str(&format!("    <itemref idref=\"{}\"/>\n", id));
    }
    opf.push_str("  </spine>\n");

    // Guide
    opf.push_str("  <guide>\n");
    opf.push_str("    <reference type=\"toc\" title=\"Table of contents\" href=\"nav.xhtml\"/>\n");
    opf.push_str("    <reference type=\"title-page\" title=\"Title\" href=\"title_page.xhtml\"/>\n");
    if let Some((first_file, first_title)) = chapters.first() {
        opf.push_str(&format!("    <reference type=\"text\" title=\"{}\" href=\"{}\"/>\n", 
            html_escape_str(first_title), first_file));
    }
    opf.push_str("  </guide>\n");

    opf.push_str("</package>\n");
    opf
}

fn generate_ncx(book: &Book, uuid: &str, chapters: &[(String, String)]) -> String {
    let mut ncx = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<ncx version=\"2005-1\" xmlns=\"http://www.daisy.org/z3986/2005/ncx/\">\n".to_string();
    ncx.push_str("  <head>\n");
    ncx.push_str("    <meta name=\"dtb:depth\" content=\"1\" />\n");
    ncx.push_str("    <meta name=\"dtb:totalPageCount\" content=\"0\" />\n");
    ncx.push_str("    <meta name=\"dtb:maxPageNumber\" content=\"0\" />\n");
    ncx.push_str("  </head>\n");
    ncx.push_str("  <docTitle>\n");
    ncx.push_str("    <text>Table of contents</text>\n");
    ncx.push_str("  </docTitle>\n");
    ncx.push_str("  <navMap>\n");

    let mut play_order = 1;

    if book.options.epub_toc_extras {
        ncx.push_str(&format!("    <navPoint playOrder=\"{}\" id=\"navPoint-{}\">\n", play_order, play_order));
        ncx.push_str("      <navLabel>\n");
        ncx.push_str("       <text>Title</text>\n");
        ncx.push_str("      </navLabel>\n");
        ncx.push_str("      <content src=\"title_page.xhtml\"/>\n");
        ncx.push_str("    </navPoint>\n");
        play_order += 1;
    }

    for (filename, title) in chapters {
        ncx.push_str(&format!("    <navPoint playOrder=\"{}\" id=\"navPoint-{}\">\n", play_order, play_order));
        ncx.push_str("      <navLabel>\n");
        ncx.push_str(&format!("       <text>{}</text>\n", html_escape_str(title)));
        ncx.push_str("      </navLabel>\n");
        ncx.push_str(&format!("      <content src=\"{}\"/>\n", filename));
        ncx.push_str("    </navPoint>\n");
        play_order += 1;
    }

    ncx.push_str("  </navMap>\n</ncx>\n");
    ncx
}

fn generate_nav(book: &Book, chapters: &[(String, String)]) -> String {
    let lang = &book.options.lang;
    let loc_toc = get_str(lang, "toc");
    let loc_title = get_str(lang, "title");

    let mut nav = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n".to_string();
    nav.push_str("<html xmlns=\"http://www.w3.org/1999/xhtml\">\n<head>\n");
    nav.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
    nav.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
    nav.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
    nav.push_str(&format!("  <title>{}</title>\n", html_escape_str(loc_toc)));
    nav.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
    nav.push_str("</head>\n<body>\n");
    nav.push_str("  <div id=\"toc\">\n");
    nav.push_str(&format!("    <h1 id=\"toc-title\">{}</h1>\n", html_escape_str(loc_toc)));
    nav.push_str("    <ol>\n");

    if book.options.epub_toc_extras {
        nav.push_str(&format!("      <li><a href=\"title_page.xhtml\">{}</a></li>\n", html_escape_str(loc_title)));
    }

    for (filename, title) in chapters {
        nav.push_str(&format!("      <li><a href=\"{}\">{}</a></li>\n", filename, html_escape_str(title)));
    }

    nav.push_str("    </ol>\n  </div>\n</body>\n</html>\n");
    nav
}

fn get_timestamp() -> String {
    // Get current UTC time in ISO 8601 format
    use std::time::{SystemTime, UNIX_EPOCH};
    let since_epoch = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = since_epoch.as_secs();

    // Simple conversion
    let days_since_epoch = secs / 86400;
    let seconds_of_day = secs % 86400;

    // This is a simplified date calculation
    // For a real implementation, we'd use a proper date library
    let year = 1970 + days_since_epoch / 365;
    let month = ((days_since_epoch % 365) / 30) + 1;
    let day = (days_since_epoch % 30) + 1;
    let hour = seconds_of_day / 3600;
    let min = (seconds_of_day % 3600) / 60;
    let sec = seconds_of_day % 60;

    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", year, month, day, hour, min, sec)
}

fn generate_uuid() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let t = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let seed = t.as_nanos() ^ (std::process::id() as u128);

    // Generate a pseudo-UUID
    let a = (seed & 0xFFFFFFFF) as u32;
    let b = ((seed >> 32) & 0xFFFF) as u16;
    let c = (((seed >> 48) & 0x0FFF) | 0x4000) as u16;
    let d = (((seed >> 64) & 0x3FFF) | 0x8000) as u16;
    let e1 = ((seed >> 80) & 0xFFFF) as u16;
    let e2 = ((seed >> 96) & 0xFFFFFFFF) as u32;

    format!("{:08x}-{:04x}-{:04x}-{:04x}-{:04x}{:08x}", a, b, c, d, e1, e2)
}

fn write_epub(path: &str, files: &EpubFiles) -> Result<(), String> {
    // Simple ZIP file writer
    use std::io::Write;

    let file = fs::File::create(path)
        .map_err(|e| format!("Could not create EPUB file '{}': {}", path, e))?;

    let mut writer = ZipWriter::new(file);

    // Write mimetype first (uncompressed, no extra data)
    writer.write_entry_uncompressed("mimetype", b"application/epub+zip")
        .map_err(|e| format!("Could not write EPUB: {}", e))?;

    // Write all other files
    for (name, content) in files.files.iter().skip(1) {
        writer.write_entry(name, content)
            .map_err(|e| format!("Could not write EPUB: {}", e))?;
    }

    writer.finish()
        .map_err(|e| format!("Could not finalize EPUB: {}", e))?;

    Ok(())
}

fn extract_plain_text_h1(tokens: &[Token]) -> String {
    for token in tokens {
        if let Token::Header(1, inner) = token {
            return extract_plain_text(inner);
        }
    }
    String::new()
}

struct EpubRenderer<'a> {
    book: &'a Book,
    link_counter: u32,
    link_counter_start: u32,
    para_counter: u32,
    footnote_counter: u32,
    chapter_idx: usize,
}

impl<'a> EpubRenderer<'a> {
    fn new(book: &'a Book) -> Self {
        EpubRenderer {
            book,
            link_counter: 0,
            link_counter_start: 0,
            para_counter: 0,
            footnote_counter: 0,
            chapter_idx: 0,
        }
    }

    fn render_chapter(&mut self, chapter: &ChapterInfo) -> String {
        let mut html = String::new();
        let lang = &self.book.options.lang;

        for (i, token) in chapter.tokens.iter().enumerate() {
            if let Token::Header(1, inner) = token {
                self.link_counter += 1;
                let link = self.link_counter;

                let num = chapter.number.unwrap_or(0);
                let should_number = self.book.options.rendering_num_depth >= 1 && num > 0;

                if chapter.is_part {
                    let part_label = self.book.get_part_label(chapter);
                    let title_text = self.render_inline(inner);
                    html.push_str(&format!("<h1 id = \"link-{}\"><span class='part-header'>{}</span>", link, html_escape_str(&part_label)));
                    if !title_text.is_empty() {
                        html.push_str(&format!("<br />{}", title_text));
                    }
                    html.push_str("</h1>");
                } else {
                    let chapter_label = if should_number {
                        let loc_chapter = if let Some(ref ch) = self.book.options.rendering_chapter {
                            ch.clone()
                        } else {
                            get_str(lang, "chapter").to_string()
                        };
                        if self.book.options.rendering_chapter_roman {
                            format!("{} {}", loc_chapter, to_roman(num))
                        } else {
                            format!("{} {}", loc_chapter, num)
                        }
                    } else {
                        String::new()
                    };

                    let title_text = self.render_inline(inner);

                    if should_number {
                        html.push_str(&format!("<h1 id = 'link-{}'><span class = 'chapter-header'>{}</span>", link, html_escape_str(&chapter_label)));
                        if !title_text.is_empty() {
                            html.push_str(&format!("<br />{}", title_text));
                        }
                        html.push_str("</h1>");
                    } else {
                        html.push_str(&format!("<h1 id = 'link-{}'>{}</h1>", link, title_text));
                    }
                }

                // Process remaining tokens
                for token2 in &chapter.tokens[i+1..] {
                    html.push_str(&self.render_token(token2));
                }
                return html;
            }

            html.push_str(&self.render_token(token));
        }

        html
    }

    fn render_token(&mut self, token: &Token) -> String {
        match token {
            Token::Paragraph(inner) => {
                self.para_counter += 1;
                let content = self.render_inline(inner);
                format!("<p id = \"para-{}\">{}</p>\n", self.para_counter, content)
            }
            Token::Header(level, inner) => {
                self.link_counter += 1;
                let content = self.render_inline(inner);
                format!("<h{} id = \"link-{}\">{}</h{}>\n", level, self.link_counter, content, level)
            }
            Token::Rule => "<p class = \"rule\">***</p>\n".to_string(),
            Token::BlockQuote(inner) => {
                let content: String = inner.iter().map(|t| self.render_token(t)).collect();
                format!("<blockquote>{}</blockquote>\n", content)
            }
            Token::List(ordered, items) => {
                let tag = if *ordered { "ol" } else { "ul" };
                let mut html = format!("<{}>\n", tag);
                for item in items {
                    self.para_counter += 1;
                    let id = self.para_counter;
                    let content = self.render_inline(&item.tokens);
                    html.push_str(&format!("<li><p id = \"para-{}\">{}</p>\n</li>\n", id, content));
                }
                html.push_str(&format!("</{}>\n", tag));
                html
            }
            Token::CodeBlock(lang, code) => {
                format!("<pre><code>{}</code></pre>\n", html_escape_str(code))
            }
            Token::Table(rows, alignments) => {
                let mut html = "<div class = \"table\">\n    <table>\n".to_string();
                for (ri, row) in rows.iter().enumerate() {
                    html.push_str("<tr>\n");
                    for cell in row {
                        let tag = if ri == 0 { "th" } else { "td" };
                        let content = self.render_inline(cell);
                        html.push_str(&format!("<{}>{}</{}>\n", tag, content, tag));
                    }
                    html.push_str("</tr>\n");
                }
                html.push_str("    </table>\n</div>\n");
                html
            }
            Token::Html(content) => {
                if self.book.options.crowbook_html_as_text {
                    format!("{}\n", html_escape_str(content))
                } else {
                    format!("{}\n", content)
                }
            }
            Token::FootnoteDef(_, _) => String::new(),
            _ => String::new(),
        }
    }

    fn render_inline(&mut self, tokens: &[Token]) -> String {
        tokens.iter().map(|t| self.render_inline_token(t)).collect()
    }

    fn render_inline_token(&mut self, token: &Token) -> String {
        match token {
            Token::Str(s) => html_escape_str(s),
            Token::Em(inner) => format!("<em>{}</em>", self.render_inline(inner)),
            Token::Strong(inner) => format!("<b>{}</b>", self.render_inline(inner)),
            Token::Strikethrough(inner) => format!("<del>{}</del>", self.render_inline(inner)),
            Token::Superscript(inner) => format!("<sup>{}</sup>", self.render_inline(inner)),
            Token::Subscript(inner) => format!("<sub>{}</sub>", self.render_inline(inner)),
            Token::Code(s) => format!("<code>{}</code>", html_escape_str(s)),
            Token::Link(href, _, inner) => {
                format!("<a href = \"{}\">{}</a>", html_escape_str(href), self.render_inline(inner))
            }
            Token::Image(href, _, alt) => {
                format!("<img src = \"{}\" alt = \"{}\" />", html_escape_str(href), html_escape_str(alt))
            }
            Token::HardBreak => "<br />".to_string(),
            Token::SoftBreak => " ".to_string(),
            _ => String::new(),
        }
    }
}

fn to_roman(n: u32) -> String {
    if n == 0 { return "0".to_string(); }
    let vals = [(1000u32, "M"), (900, "CM"), (500, "D"), (400, "CD"),
                (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
                (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")];
    let mut result = String::new();
    let mut n = n;
    for (val, sym) in &vals {
        while n >= *val {
            result.push_str(sym);
            n -= val;
        }
    }
    result
}

// Simple ZIP writer implementation
struct ZipWriter<W: std::io::Write + std::io::Seek> {
    writer: W,
    entries: Vec<ZipEntry>,
    offset: u32,
}

struct ZipEntry {
    name: String,
    offset: u32,
    size: u32,
    crc32: u32,
    method: u16,
    compressed_size: u32,
}

impl<W: std::io::Write + std::io::Seek> ZipWriter<W> {
    fn new(writer: W) -> Self {
        ZipWriter {
            writer,
            entries: Vec::new(),
            offset: 0,
        }
    }

    fn write_entry_uncompressed(&mut self, name: &str, data: &[u8]) -> Result<(), std::io::Error> {
        use std::io::Write;

        let crc = crc32(data);
        let name_bytes = name.as_bytes();

        // Local file header
        let header = self.make_local_header(name_bytes, data.len() as u32, data.len() as u32, crc, 0);
        self.writer.write_all(&header)?;
        self.writer.write_all(data)?;

        let entry_size = header.len() as u32 + data.len() as u32;

        self.entries.push(ZipEntry {
            name: name.to_string(),
            offset: self.offset,
            size: data.len() as u32,
            crc32: crc,
            method: 0,
            compressed_size: data.len() as u32,
        });

        self.offset += entry_size;
        Ok(())
    }

    fn write_entry(&mut self, name: &str, data: &[u8]) -> Result<(), std::io::Error> {
        // Use store (no compression) for simplicity
        self.write_entry_uncompressed(name, data)
    }

    fn make_local_header(&self, name: &[u8], size: u32, comp_size: u32, crc: u32, method: u16) -> Vec<u8> {
        let mut h = Vec::new();
        // Signature
        h.extend_from_slice(&[0x50, 0x4B, 0x03, 0x04]);
        // Version needed
        h.extend_from_slice(&[20u8, 0]);
        // General purpose bit flag
        h.extend_from_slice(&[0, 0]);
        // Compression method
        h.extend_from_slice(&method.to_le_bytes());
        // Last mod file time/date (use fixed date)
        h.extend_from_slice(&[0, 0, 0, 0]);
        // CRC-32
        h.extend_from_slice(&crc.to_le_bytes());
        // Compressed size
        h.extend_from_slice(&comp_size.to_le_bytes());
        // Uncompressed size
        h.extend_from_slice(&size.to_le_bytes());
        // File name length
        h.extend_from_slice(&(name.len() as u16).to_le_bytes());
        // Extra field length
        h.extend_from_slice(&[0, 0]);
        // File name
        h.extend_from_slice(name);
        h
    }

    fn finish(&mut self) -> Result<(), std::io::Error> {
        use std::io::Write;

        let central_dir_offset = self.offset;
        let mut central_dir_size = 0u32;

        // Write central directory
        for entry in &self.entries {
            let name_bytes = entry.name.as_bytes();
            let mut rec = Vec::new();
            // Signature
            rec.extend_from_slice(&[0x50, 0x4B, 0x01, 0x02]);
            // Version made by
            rec.extend_from_slice(&[20u8, 0]);
            // Version needed
            rec.extend_from_slice(&[20u8, 0]);
            // General purpose
            rec.extend_from_slice(&[0, 0]);
            // Compression
            rec.extend_from_slice(&entry.method.to_le_bytes());
            // Mod time/date
            rec.extend_from_slice(&[0, 0, 0, 0]);
            // CRC
            rec.extend_from_slice(&entry.crc32.to_le_bytes());
            // Compressed size
            rec.extend_from_slice(&entry.compressed_size.to_le_bytes());
            // Uncompressed size
            rec.extend_from_slice(&entry.size.to_le_bytes());
            // Filename length
            rec.extend_from_slice(&(name_bytes.len() as u16).to_le_bytes());
            // Extra field length
            rec.extend_from_slice(&[0, 0]);
            // File comment length
            rec.extend_from_slice(&[0, 0]);
            // Disk number start
            rec.extend_from_slice(&[0, 0]);
            // Internal attributes
            rec.extend_from_slice(&[0, 0]);
            // External attributes
            rec.extend_from_slice(&[0, 0, 0, 0]);
            // Relative offset
            rec.extend_from_slice(&entry.offset.to_le_bytes());
            // Filename
            rec.extend_from_slice(name_bytes);

            self.writer.write_all(&rec)?;
            central_dir_size += rec.len() as u32;
        }

        // End of central directory
        let mut eocd = Vec::new();
        eocd.extend_from_slice(&[0x50, 0x4B, 0x05, 0x06]);
        // Disk number
        eocd.extend_from_slice(&[0, 0]);
        // Disk with start
        eocd.extend_from_slice(&[0, 0]);
        // Entries on disk
        eocd.extend_from_slice(&(self.entries.len() as u16).to_le_bytes());
        // Total entries
        eocd.extend_from_slice(&(self.entries.len() as u16).to_le_bytes());
        // Central dir size
        eocd.extend_from_slice(&central_dir_size.to_le_bytes());
        // Central dir offset
        eocd.extend_from_slice(&central_dir_offset.to_le_bytes());
        // Comment length
        eocd.extend_from_slice(&[0, 0]);

        self.writer.write_all(&eocd)?;
        Ok(())
    }
}

fn crc32(data: &[u8]) -> u32 {
    // CRC-32 implementation
    let mut crc: u32 = 0xFFFFFFFF;

    for &byte in data {
        let table_idx = ((crc ^ byte as u32) & 0xFF) as usize;
        crc = CRC32_TABLE[table_idx] ^ (crc >> 8);
    }

    !crc
}

static CRC32_TABLE: [u32; 256] = {
    let mut table = [0u32; 256];
    let mut i = 0;
    while i < 256 {
        let mut c = i as u32;
        let mut j = 0;
        while j < 8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1);
            } else {
                c >>= 1;
            }
            j += 1;
        }
        table[i] = c;
        i += 1;
    }
    table
};
