fn render_epub_titlepage(template: &str, book: &Book) -> String {
    let lang = &book.options.lang;
    let has_subtitle = book.options.subtitle.is_some();
    let has_autograph = book.options.autograph.is_some();

    let mut result = template.to_string();

    // Process if blocks
    let flags = [("has_subtitle", has_subtitle), ("has_autograph", has_autograph)];
    for (flag, value) in &flags {
        let if_tag = format!("{{% if {}%}}", flag);
        let if_tag2 = format!("{{% if {} %}}", flag);
        let endif_tag = "{% endif %}";

        for tag in &[if_tag, if_tag2] {
            while let Some(start) = result.find(tag.as_str()) {
                if let Some(end_pos) = result[start + tag.len()..].find(endif_tag) {
                    let block_start = start + tag.len();
                    let block_end = block_start + end_pos;
                    let inner = result[block_start..block_end].to_string();
                    let replacement = if *value { inner } else { String::new() };
                    result = format!("{}{}{}", &result[..start], replacement, &result[block_end + endif_tag.len()..]);
                } else {
                    break;
                }
            }
        }
    }

    result = result.replace("{{lang}}", lang);
    result = result.replace("{{author}}", &html_escape_str(&book.options.author));
    result = result.replace("{{title_raw}}", &book.options.title);
    result = result.replace("{{title}}", &html_escape_str(&book.options.title));
    result = result.replace("{{subtitle}}", &html_escape_str(book.options.subtitle.as_deref().unwrap_or("")));
    result = result.replace("{{autograph}}", &html_escape_str(book.options.autograph.as_deref().unwrap_or("")));

    result
}

fn render_epub_chapter(template: &str, content: &str, title: &str, lang: &str) -> String {
    let mut result = template.to_string();
    result = result.replace("{{lang}}", lang);
    result = result.replace("{{chapter_title_raw}}", &html_escape_str(title));
    result = result.replace("{{content}}", content);
    result
}

fn generate_opf(book: &Book, uuid: &str, chapters: &[(String, String)], warnings: &mut Vec<String>) -> String {
    let lang = &book.options.lang;
    let version = book.options.epub_version;

    let version_str = if version >= 3 { "3.0" } else { "2.0" };

