pub fn render_epub(book: &Book, output: Option<&str>) -> Result<Vec<String>, String> {
    let mut warnings = Vec::new();

    // Check if zip command exists
    let can_zip = check_zip_command(&book.options.crowbook_zip_command);
    if !can_zip {
        warnings.push("Could not run zip command, falling back to zip library".to_string());
    }

    // Check for conflicting chapters (multiple h1 in same file)
    for chapter in &book.chapters {
        let h1_count = count_h1(&chapter.tokens);
        if h1_count > 1 {
            warnings.push(format!("EPUB ({}): detected two chapters inside the same markdown file.", chapter.filename));
        }
    }

    // Generate EPUB content
    let epub_data = generate_epub(book, &mut warnings)?;

    let out_path = match output {
        Some(p) => p.to_string(),
        None => {
            // Try to derive from book title
            format!("{}.epub", sanitize_filename(&book.options.title))
        }
    };

    let full_path = if Path::new(&out_path).is_absolute() {
        std::path::PathBuf::from(&out_path)
    } else {
        book.base_dir.join(&out_path)
    };

    // Write the EPUB (zip) file
    write_epub(&full_path.to_string_lossy(), &epub_data)?;

    Ok(warnings)
}

fn count_h1(tokens: &[Token]) -> usize {
    let mut count = 0;
    for token in tokens {
        if let Token::Header(1, _) = token {
            count += 1;
        }
    }
    count
}

fn check_zip_command(cmd: &str) -> bool {
