fn process_latex_template(template: &str, vars: &HashMap<String, String>, conditions: &[(&str, bool)]) -> String {
    let mut result = template.to_string();

    // Process <# if cond #> ... <# endif #> blocks
    // Also handle <# else #>
    loop {
        let if_start = result.find("<# if ");
        if if_start.is_none() { break; }
        let if_start = if_start.unwrap();

        let endif = "<# endif #>";
        let else_tag = "<# else #>";

        // Find condition end
        let cond_end = result[if_start..].find(" #>");
        if cond_end.is_none() { break; }
        let cond_end = if_start + cond_end.unwrap();

        let cond = result[if_start + 6..cond_end].trim().to_string();
        let block_start = cond_end + 3;

        // Find matching endif
        let block = &result[block_start..];
        let endif_pos = find_matching_endif(block);
        if endif_pos.is_none() { break; }
        let endif_pos = endif_pos.unwrap();

        // Check for else
        let (true_block, false_block) = if let Some(else_pos) = block[..endif_pos].find(else_tag) {
            (&block[..else_pos], &block[else_pos + else_tag.len()..endif_pos])
        } else {
            (&block[..endif_pos], "")
        };

        // Evaluate condition
        let cond_value = evaluate_condition(&cond, conditions);

        let replacement = if cond_value { true_block } else { false_block };

        let full_end = block_start + endif_pos + endif.len();
        result = format!("{}{}{}", &result[..if_start], replacement, &result[full_end..]);
    }

    // Replace <<variable>> with values
    let mut final_result = String::new();
    let chars: Vec<char> = result.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '<' && i + 1 < chars.len() && chars[i+1] == '<' {
            // Find closing >>
            let start = i + 2;
            if let Some(end_offset) = chars[start..].iter().enumerate()
                .find(|(j, &c)| c == '>' && start + j + 1 < chars.len() && chars[start + j + 1] == '>')
                .map(|(j, _)| j)
            {
                let var_name: String = chars[start..start + end_offset].iter().collect();
                if let Some(val) = vars.get(var_name.trim()) {
                    final_result.push_str(val);
                }
                i = start + end_offset + 2;
                continue;
            }
        }
        final_result.push(chars[i]);
        i += 1;
    }

    final_result
}

fn find_matching_endif(text: &str) -> Option<usize> {
    let endif = "<# endif #>";
    let if_open = "<# if ";
    let mut depth = 0;
    let mut pos = 0;

    while pos < text.len() {
        if text[pos..].starts_with(if_open) {
            depth += 1;
        } else if text[pos..].starts_with(endif) {
            if depth == 0 {
                return Some(pos);
            }
            depth -= 1;
        }
        // Move forward by 1 char
        pos += 1;
    }
    None
}

fn evaluate_condition(cond: &str, conditions: &[(&str, bool)]) -> bool {
    let cond = cond.trim();

    // Handle "not X"
    if cond.starts_with("not ") {
        let inner = &cond[4..].trim();
        return !evaluate_condition(inner, conditions);
    }

    // Look up in conditions
    for (name, value) in conditions {
        if *name == cond {
            return *value;
        }
    }

    false
}

fn latex_escape(s: &str) -> String {
    s.replace('&', "\\&")
     .replace('%', "\\%")
     .replace('$', "\\$")
     .replace('#', "\\#")
     .replace('_', "\\_")
     .replace('{', "\\{")
     .replace('}', "\\}")
     .replace('~', "\\textasciitilde{}")
     .replace('^', "\\textasciicircum{}")
     .replace('\\', "\\textbackslash{}")
