    }

    fn render_table_latex(&mut self, rows: &[Vec<Vec<Token>>], alignments: &[Alignment]) -> String {
        let col_spec: String = alignments.iter().map(|a| match a {
            Alignment::Left => "|X",
            Alignment::Right => "|X",
            Alignment::Center => "|X",
            Alignment::None => "|X",
        }).collect::<Vec<_>>().join("") + "|";

        let mut tex = format!("\\begin{{mdtable}}{{{}}}\n\\hline\n", col_spec);

        for (ri, row) in rows.iter().enumerate() {
            let cells: Vec<String> = row.iter().map(|cell| self.render_inline(cell)).collect();
            tex.push_str(&cells.join(" & "));
            tex.push_str("\\\\ \n");
            if ri == 0 {
                tex.push_str("\\hline\n");
            }
        }

        tex.push_str("\\hline\n\\end{mdtable}\n");
        tex
    }
