        if if_start.is_none() { break; }
        let if_start = if_start.unwrap();

        let endif = "<# endif #>";
        let else_tag = "<# else #>";

        // Find condition end
        let cond_end = result[if_start..].find(" #>");
        if cond_end.is_none() { break; }
        let cond_end = if_start + cond_end.unwrap();

        let cond = result[if_start + 6..cond_end].trim().to_string();
        let block_start = cond_end + 3;

        // Find matching endif
        let block = &result[block_start..];
        let endif_pos = find_matching_endif(block);
        if endif_pos.is_none() { break; }
        let endif_pos = endif_pos.unwrap();

        // Check for else
        let (true_block, false_block) = if let Some(else_pos) = block[..endif_pos].find(else_tag) {
            (&block[..else_pos], &block[else_pos + else_tag.len()..endif_pos])
        } else {
            (&block[..endif_pos], "")
        };

        // Evaluate condition
        let cond_value = evaluate_condition(&cond, conditions);

        let replacement = if cond_value { true_block } else { false_block };

        let full_end = block_start + endif_pos + endif.len();
        result = format!("{}{}{}", &result[..if_start], replacement, &result[full_end..]);
    }

    // Replace <<variable>> with values
    let mut final_result = String::new();
    let chars: Vec<char> = result.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '<' && i + 1 < chars.len() && chars[i+1] == '<' {
            // Find closing >>
            let start = i + 2;
            if let Some(end_offset) = chars[start..].iter().enumerate()
                .find(|(j, &c)| c == '>' && start + j + 1 < chars.len() && chars[start + j + 1] == '>')
                .map(|(j, _)| j)
            {
                let var_name: String = chars[start..start + end_offset].iter().collect();
                if let Some(val) = vars.get(var_name.trim()) {
                    final_result.push_str(val);
                }
                i = start + end_offset + 2;
                continue;
            }
        }
        final_result.push(chars[i]);
        i += 1;
    }

    final_result
}

fn find_matching_endif(text: &str) -> Option<usize> {
    let endif = "<# endif #>";
    let if_open = "<# if ";
    let mut depth = 0;
    let mut pos = 0;

    while pos < text.len() {
        if text[pos..].starts_with(if_open) {
            depth += 1;
        } else if text[pos..].starts_with(endif) {
            if depth == 0 {
                return Some(pos);
            }
            depth -= 1;
        }
        // Move forward by 1 char
        pos += 1;
    }
    None
}

fn evaluate_condition(cond: &str, conditions: &[(&str, bool)]) -> bool {
    let cond = cond.trim();

    // Handle "not X"
    if cond.starts_with("not ") {
        let inner = &cond[4..].trim();
        return !evaluate_condition(inner, conditions);
    }

    // Look up in conditions
    for (name, value) in conditions {
        if *name == cond {
            return *value;
        }
    }

    false
}

fn latex_escape(s: &str) -> String {
    s.replace('&', "\\&")
     .replace('%', "\\%")
     .replace('$', "\\$")
     .replace('#', "\\#")
     .replace('_', "\\_")
     .replace('{', "\\{")
     .replace('}', "\\}")
     .replace('~', "\\textasciitilde{}")
     .replace('^', "\\textasciicircum{}")
     .replace('\\', "\\textbackslash{}")
}

fn get_babel_lang(lang: &str) -> &'static str {
    match lang {
        "en" => "english",
        "fr" => "french",
        "de" => "german",
        "es" => "spanish",
        "it" => "italian",
        "pt" => "portuguese",
        "nl" => "dutch",
        "pl" => "polish",
        "ru" => "russian",
        "sv" => "swedish",
        "no" => "norsk",
        "da" => "danish",
        "fi" => "finnish",
        "ca" => "catalan",
        _ => "english",
    }
}

struct LatexRenderer<'a> {
    book: &'a Book,
    chapter_idx: usize,
    link_counter: u32,
    para_counter: u32,
    used_strikethrough: bool,
    used_taskitem: bool,
    used_codeblocks: bool,
    used_images: bool,
    used_tables: bool,
}

impl<'a> LatexRenderer<'a> {
    fn new(book: &'a Book) -> Self {
        LatexRenderer {
            book,
            chapter_idx: 0,
            link_counter: 0,
            para_counter: 0,
            used_strikethrough: false,
            used_taskitem: false,
            used_codeblocks: false,
            used_images: false,
            used_tables: false,
        }
    }

    fn render_chapter(&mut self, chapter: &crate::book::ChapterInfo) -> String {
        // Pre-scan for features
        self.scan_features(&chapter.tokens);

        let mut latex = String::new();
        let is_book = self.book.options.tex_class == "book";
        let lang = &self.book.options.lang;

        let num = chapter.number.unwrap_or(0);

        for (i, token) in chapter.tokens.iter().enumerate() {
            if let Token::Header(1, inner) = token {
                self.link_counter += 1;
                let label = format!("chapter-{}", self.chapter_idx);
                let title = extract_plain_text(inner);

                if chapter.is_part {
                    if is_book {
                        latex.push_str(&format!("\\part{{{}}}\n\\label{{{}}}\n", latex_escape(&title), label));
                    } else {
                        latex.push_str(&format!("\\section{{{}}}\n\\label{{{}}}\n", latex_escape(&title), label));
                    }
                } else {
                    if is_book {
                        latex.push_str(&format!("\\chapter{{{}}}\n\\label{{{}}}\n", latex_escape(&title), label));
                    } else {
                        latex.push_str(&format!("\\section{{{}}}\n\\label{{{}}}\n", latex_escape(&title), label));
                    }
                }

                // Process rest
                for token2 in &chapter.tokens[i+1..] {
                    latex.push_str(&self.render_token(token2));
                }
                return latex;
            }

            latex.push_str(&self.render_token(token));
        }

        latex
    }

    fn scan_features(&mut self, tokens: &[Token]) {
        for token in tokens {
            match token {
                Token::Strikethrough(_) => self.used_strikethrough = true,
                Token::CodeBlock(_, _) => self.used_codeblocks = true,
                Token::Image(_, _, _) => self.used_images = true,
                Token::Table(_, _) => self.used_tables = true,
                Token::List(_, items) => {
                    for item in items {
                        if item.is_task.is_some() {
                            self.used_taskitem = true;
                        }
                        self.scan_features(&item.tokens);
                    }
                }
                Token::Paragraph(inner) | Token::Header(_, inner) | Token::Em(inner) 
                | Token::Strong(inner) | Token::BlockQuote(inner) => {
                    self.scan_features(inner);
                }
                _ => {}
            }
        }
    }

    fn render_token(&mut self, token: &Token) -> String {
        match token {
            Token::Paragraph(inner) => {
                format!("{}\n\n", self.render_inline(inner))
            }
            Token::Header(level, inner) => {
                self.link_counter += 1;
                let title = extract_plain_text(inner);
                let cmd = match level {
                    2 => if self.book.options.tex_class == "book" { "\\section" } else { "\\subsection" },
                    3 => if self.book.options.tex_class == "book" { "\\subsection" } else { "\\subsubsection" },
                    4 => "\\subsubsection",
                    5 | 6 => "\\paragraph",
                    _ => "\\section",
                };
                format!("{}{{{}}}\n", cmd, latex_escape(&title))
            }
            Token::Rule => "\\mdrule\n".to_string(),
            Token::BlockQuote(inner) => {
                let content: String = inner.iter().map(|t| self.render_token(t)).collect();
                format!("\\begin{{mdblockquote}}\n{}\n\\end{{mdblockquote}}\n", content)
            }
            Token::List(ordered, items) => {
                let (begin, end) = if *ordered { ("enumerate", "enumerate") } else { ("itemize", "itemize") };
                let mut tex = format!("\\begin{{{}}}\n", begin);
                for item in items {
                    tex.push_str("\\item ");
                    tex.push_str(&self.render_inline(&item.tokens));
                    tex.push_str("\n\n");
                }
                tex.push_str(&format!("\\end{{{}}}", end));
                tex.push('\n');
                tex
            }
            Token::CodeBlock(lang, code) => {
                self.used_codeblocks = true;
                format!("\\begin{{mdcodeblock}}\n{{\\sloppy {}}}\n\\end{{mdcodeblock}}", self.render_code_latex(code))
            }
            Token::Table(rows, alignments) => {
                self.used_tables = true;
                self.render_table_latex(rows, alignments)
            }
            Token::Html(content) => {
                // Escape HTML content in LaTeX
                format!("{}\n", latex_escape(content))
            }
            _ => String::new(),
        }
    }

    fn render_inline(&mut self, tokens: &[Token]) -> String {
        tokens.iter().map(|t| self.render_inline_token(t)).collect()
    }

    fn render_inline_token(&mut self, token: &Token) -> String {
        match token {
            Token::Str(s) => latex_escape(s),
            Token::Em(inner) => format!("\\emph{{{}}}", self.render_inline(inner)),
            Token::Strong(inner) => format!("\\mdstrong{{{}}}", self.render_inline(inner)),
            Token::Strikethrough(inner) => {
                self.used_strikethrough = true;
                format!("\\sout{{{}}}", self.render_inline(inner))
            }
            Token::Superscript(inner) => format!("\\textsuperscript{{{}}}", self.render_inline(inner)),
            Token::Subscript(inner) => format!("\\textsubscript{{{}}}", self.render_inline(inner)),
            Token::Code(s) => format!("\\mdcode{{{}}}", latex_escape(s)),
            Token::Link(href, _, inner) => {
                let content = self.render_inline(inner);
                if self.book.options.tex_links_as_footnotes {
                    format!("\\href{{{}}}{{{}}}{}", 
                        href, content,
                        format!("\\protect\\footnote{{\\url{{{}}}}}", href))
                } else {
                    format!("\\href{{{}}}{{{}}}", href, content)
                }
            }
            Token::Image(href, _, alt) => {
                self.used_images = true;
                format!("\\mdstandaloneimage{{{}}}", href)
            }
            Token::HardBreak => "\\mdhardbreak\n".to_string(),
            Token::SoftBreak => " ".to_string(),
            _ => String::new(),
        }
    }

    fn render_code_latex(&self, code: &str) -> String {
        // Simple code rendering
        let escaped = code
            .replace('\\', "\\textbackslash{}")
            .replace('{', "\\{")
            .replace('}', "\\}")
            .replace(' ', "\\hphantom{ }\\allowbreak{}")
            .replace('\n', "\\\\{}\n");
        format!("\\texttt{{{}}}", escaped)
    }

    fn render_table_latex(&mut self, rows: &[Vec<Vec<Token>>], alignments: &[Alignment]) -> String {
        let col_spec: String = alignments.iter().map(|a| match a {
            Alignment::Left => "|X",
            Alignment::Right => "|X",
            Alignment::Center => "|X",
            Alignment::None => "|X",
        }).collect::<Vec<_>>().join("") + "|";

        let mut tex = format!("\\begin{{mdtable}}{{{}}}\n\\hline\n", col_spec);

        for (ri, row) in rows.iter().enumerate() {
            let cells: Vec<String> = row.iter().map(|cell| self.render_inline(cell)).collect();
            tex.push_str(&cells.join(" & "));
            tex.push_str("\\\\ \n");
            if ri == 0 {
                tex.push_str("\\hline\n");
            }
        }

        tex.push_str("\\hline\n\\end{mdtable}\n");
        tex
    }
}
