                "-a" | "--autograph" => a.autograph = true,
                "-S" | "--stats" => a.stats = true,
                "-l" | "--list-options" => a.list_options = true,
                "-o" | "--output" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--output requires an argument".to_string());
                    }
                    a.output = Some(args[i].clone());
                }
                "-t" | "--to" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--to requires an argument".to_string());
                    }
                    a.to_format = Some(args[i].clone());
                }
                "-L" | "--lang" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--lang requires an argument".to_string());
                    }
                    a.lang = Some(args[i].clone());
                }
                "--print-template" => {
                    i += 1;
                    if i >= args.len() {
                        return Err("--print-template requires an argument".to_string());
                    }
                    a.print_template = Some(args[i].clone());
                }
                "-c" | "--create" => {
                    i += 1;
                    let mut files = vec![];
                    while i < args.len() && !args[i].starts_with('-') {
                        files.push(args[i].clone());
                        i += 1;
                    }
                    a.create = Some(files);
                    continue;
                }
                "--set" => {
                    i += 1;
                    while i + 1 < args.len() && !args[i].starts_with('-') {
                        let key = args[i].clone();
                        let val = args[i + 1].clone();
                        if val.starts_with('-') {
                            break;
                        }
                        a.set_options.push((key, val));
                        i += 2;
                    }
                    continue;
                }
                _ => {
                    if arg.starts_with('-') {
                        return Err(format!("the following required arguments were not provided:\n  --to <to>\n\nUsage: executable --to <to> --create <files>... --output <output> [BOOK]\n\nFor more information, try '--help'."));
