                "-c" | "--create" => {
                    i += 1;
                    let mut files = vec![];
                    while i < args.len() && !args[i].starts_with('-') {
                        files.push(args[i].clone());
                        i += 1;
                    }
                    a.create = Some(files);
                    continue;
                }
                "--set" => {
                    i += 1;
                    while i + 1 < args.len() && !args[i].starts_with('-') {
                        let key = args[i].clone();
                        let val = args[i + 1].clone();
                        if val.starts_with('-') {
                            break;
                        }
                        a.set_options.push((key, val));
                        i += 2;
                    }
                    continue;
                }
                _ => {
                    if arg.starts_with('-') {
                        return Err(format!("the following required arguments were not provided:\n  --to <to>\n\nUsage: executable --to <to> --create <files>... --output <output> [BOOK]\n\nFor more information, try '--help'."));
                    }
                    a.book_file = Some(arg.clone());
                }
            }
            i += 1;
        }

        Ok(a)
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let parsed = match Args::parse(&args) {
        Ok(a) => a,
        Err(e) => {
            eprintln!("error: {}", e);
            process::exit(1);
        }
    };

    if parsed.help {
        print_help();
        return;
    }

    if parsed.version {
        print_version();
        return;
    }

    if parsed.list_options {
        eprintln!("CROWBOOK 0.17.0");
        book::print_options();
        return;
    }

    if let Some(ref template_name) = parsed.print_template {
        eprintln!("CROWBOOK 0.17.0");
        match templates::get_template(template_name) {
            Ok(content) => print!("{}", content),
            Err(e) => {
                eprintln!("ERROR {}", e);
                process::exit(1);
            }
        }
        return;
    }

    if let Some(ref files) = parsed.create {
        let to_format = parsed.to_format.as_deref().unwrap_or("epub");

        // Check for required --to argument
        if parsed.to_format.is_none() {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  --to <to>");
            eprintln!("");
            eprintln!("Usage: executable --to <to> --create <files>... --output <output> [BOOK]");
            eprintln!("");
            eprintln!("For more information, try '--help'.");
            process::exit(1);
        }

        eprintln!("CROWBOOK 0.17.0");
        println!("\"author: Your name\"");
        println!("\"title: Your title\"");
        println!("\"lang: en\"");
        println!();
        println!("\"## Output formats\"");
        println!();
        println!("\"# Uncomment and fill to generate files\"");
        println!("\"# output.html: some_file.html\"");
        println!("\"# output.epub: some_file.epub\"");
        println!("\"# output.pdf: some_file.pdf\"");
        println!();
        println!("\"# Or uncomment the following to generate PDF, HTML and EPUB files based on this file's name\"");
        println!("\"# output: [pdf, epub, html]\"");
        println!();
        println!("\"# Uncomment and fill to set cover image (for EPUB)\"");
        println!("\"# cover: some_cover.png\"");
        println!();
        println!("## List of chapters");
        for file in files {
            println!("+ {}", file);
        }
        return;
    }

    let book_file = match parsed.book_file {
        Some(ref f) => f.clone(),
        None => {
            eprintln!("error: the following required arguments were not provided:");
            eprintln!("  <BOOK>");
            eprintln!("");
            eprintln!("Usage: executable [OPTIONS] [BOOK]");
            eprintln!("");
            eprintln!("For more information, try '--help'.");
            process::exit(1);
        }
    };

    if !parsed.quiet {
        eprintln!("CROWBOOK 0.17.0");
    }

    let mut book = book::Book::new();

    if let Some(ref lang) = parsed.lang {
        book.set_runtime_lang(lang.clone());
    }

    // Apply pre-load set options
    for (key, val) in &parsed.set_options {
        let _ = book.set_option(key, val);
    }

    // Load the book
    let result = if parsed.single {
        book.load_single_markdown(&book_file)
    } else {
        book.load_config(&book_file)
    };

    if let Err(e) = result {
        eprintln!("ERROR {}", e);
        process::exit(1);
    }

    // Apply post-load set options (override)
    for (key, val) in &parsed.set_options {
        let _ = book.set_option(key, val);
    }

    if parsed.stats {
        book.print_stats();
        return;
    }

    if parsed.autograph {
        eprint!("Please enter your autograph: ");
        let mut autograph = String::new();
        std::io::stdin().read_line(&mut autograph).unwrap_or(0);
        let autograph = autograph.trim().to_string();
        book.set_autograph(autograph);
    }

    let errors = book.render_all(
        parsed.to_format.as_deref(),
        parsed.output.as_deref(),
        parsed.verbose
    );

    if !errors.is_empty() {
        let mut has_real_errors = false;
        let mut warnings = Vec::new();

        for e in &errors {
            if e.starts_with("ERROR ") {
                has_real_errors = true;
                eprintln!("{}", e);
            } else {
                warnings.push(e.clone());
            }
        }

        if !warnings.is_empty() {
            eprintln!("WARNING Crowbook exited successfully, but the following errors occurred:");
            for w in &warnings {
                eprintln!("WARNING {}", w);
            }
        }

        if has_real_errors {
            process::exit(1);
        }
    }
}
