# Add smart_quotes function
smart_quotes_fn = '''
fn apply_smart_quotes(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut result = String::with_capacity(text.len());

    for (i, &c) in chars.iter().enumerate() {
        if c == '"' {
            // Determine if this is an opening or closing quote
            let prev = if i > 0 { chars[i - 1] } else { ' ' };
            let next = if i + 1 < chars.len() { chars[i + 1] } else { ' ' };

            // Opening quote: after whitespace, (, [, {, =, < or at start
            let is_opening = prev == ' ' || prev == '\\t' || prev == '\\n' 
                || prev == '(' || prev == '[' || prev == '{' 
                || prev == '=' || prev == '<'
                || i == 0;

            if is_opening {
                result.push('\\u{201C}');  // LEFT DOUBLE QUOTATION MARK
            } else {
                result.push('\\u{201D}');  // RIGHT DOUBLE QUOTATION MARK
            }
        } else if c == '\\'' {
            // Smart single quotes
            let prev = if i > 0 { chars[i - 1] } else { ' ' };
            let is_opening = prev == ' ' || prev == '\\t' || prev == '\\n'
                || prev == '(' || prev == '[' || prev == '{'
                || i == 0;

            if is_opening {
                result.push('\\u{2018}');  // LEFT SINGLE QUOTATION MARK
            } else {
                result.push('\\u{2019}');  // RIGHT SINGLE QUOTATION MARK
            }
        } else {
            result.push(c);
        }
    }

    result
}
'''

