            opf.push_str(&format!("    <dc:creator id=\"epub-creator-1\">{}</dc:creator>\n", html_escape_str(&book.options.author)));
            opf.push_str("    <meta refines=\"#epub-creator-1\" property=\"role\" scheme=\"marc:relators\">aut</meta>\n");
        } else {
            opf.push_str(&format!("    <dc:creator opf:role=\"aut\">{}</dc:creator>\n", html_escape_str(&book.options.author)));
