            }
            if let Some(s) = subject {
                opf.push_str(&format!("    <dc:subject>{}</dc:subject>\n", html_escape_str(s)));
            }
            if let Some(l) = license {
                opf.push_str(&format!("    <dc:rights>{}</dc:rights>\n", html_escape_str(l)));
            }
        } else {
            opf.push_str("\n");  // Empty string when no optional fields
        }
    } else {
        // No author: just empty string
        opf.push_str("\n");
    }

