    }

    opf.push_str("    <item media-type=\"application/xhtml+xml\" id=\"id_title_page.xhtml\" href=\"title_page.xhtml\"/>\n");

    for (filename, _) in chapters {
        let id = format!("id_{}", filename);
        opf.push_str(&format!("    <item media-type=\"application/xhtml+xml\" id=\"{}\" href=\"{}\"/>\n", id, filename));
    }

    opf.push_str("    <item media-type=\"text/css\" id=\"id_stylesheet.css\" href=\"stylesheet.css\"/>\n");
    opf.push_str("  </manifest>\n");

    // Spine
    let dir_attr = if version >= 3 { " page-progression-direction=\"ltr\"" } else { "" };
    opf.push_str(&format!("  <spine toc=\"ncx\"{}>\n", dir_attr));
    opf.push_str("    <itemref idref=\"id_title_page.xhtml\"/>\n");
    for (filename, _) in chapters {
        let id = format!("id_{}", filename);
        opf.push_str(&format!("    <itemref idref=\"{}\"/>\n", id));
    }
    opf.push_str("  </spine>\n");

    // Guide
    opf.push_str("  <guide>\n");
    opf.push_str("    <reference type=\"toc\" title=\"Table of contents\" href=\"nav.xhtml\"/>\n");
    opf.push_str("    <reference type=\"title-page\" title=\"Title\" href=\"title_page.xhtml\"/>\n");
    if let Some((first_file, first_title)) = chapters.first() {
        opf.push_str(&format!("    <reference type=\"text\" title=\"{}\" href=\"{}\"/>\n", 
            html_escape_str(first_title), first_file));
    }
    opf.push_str("  </guide>\n");

    opf.push_str("</package>\n");
    opf
}"""

    content = content[:idx] + new_fn + '\n' + content[end:]
